	.rl-next__link{display:flex;align-items:center;gap:12px;padding:10px 44px 10px 10px;background:rgba(31,31,31,.97);border:1.5px solid var(--rl-line);border-radius:18px;box-shadow:0 10px 30px rgba(0,0,0,.5);color:var(--rl-ink);backdrop-filter:blur(10px)}
