/* Interaktívny graf (čistý SVG, bez knižníc): hover/dotyk/klávesnica, prepínač Mesačne/Spolu. */
(function () {
	'use strict';
	var root = document.querySelector('.js-chart');
	if (!root) { return; }
	var pts;
	try { pts = JSON.parse(root.getAttribute('data-points') || '[]'); } catch (e) { pts = []; }
	if (!pts.length) { return; }
	var unit = root.getAttribute('data-unit') || '';
	var area = root.querySelector('.js-chart-area');
	var totalEl = root.querySelector('.js-chart-total');
	var NS = 'http://www.w3.org/2000/svg';
	var mode = 'month';
	var fmt = function (n) { return n.toLocaleString('sk-SK'); };

	function series() {
		if (mode === 'month') { return pts.map(function (p) { return p.value; }); }
		var s = 0;
		return pts.map(function (p) { s += p.value; return s; });
	}
	function niceMax(v) {
		var p = Math.pow(10, Math.floor(Math.log10(v || 1)));
		var n = v / p;
		return (n <= 1 ? 1 : n <= 2 ? 2 : n <= 5 ? 5 : 10) * p;
	}
	function el(name, attrs) {
		var e = document.createElementNS(NS, name);
		for (var k in attrs) { e.setAttribute(k, attrs[k]); }
		return e;
	}

	var tip = document.createElement('div');
	tip.className = 'rl-chart__tip';
	tip.hidden = true;
	area.appendChild(tip);

	function draw(animate) {
		var old = area.querySelector('svg');
		if (old) { area.removeChild(old); }
		var w = Math.max(area.clientWidth, 280);
		var h = w < 520 ? 260 : 340;
		var m = { t: 16, r: 18, b: 34, l: 46 };
		var data = series();
		var max = niceMax(Math.max.apply(null, data) * 1.05);
		var iw = w - m.l - m.r, ih = h - m.t - m.b;
		var x = function (i) { return m.l + (data.length === 1 ? iw / 2 : (iw * i) / (data.length - 1)); };
		var y = function (v) { return m.t + ih - (v / max) * ih; };
		var svg = el('svg', { viewBox: '0 0 ' + w + ' ' + h, width: w, height: h, role: 'img', 'aria-label': 'Graf' });

		for (var g = 0; g <= 4; g++) {
			var gv = (max / 4) * g, gy = y(gv);
			svg.appendChild(el('line', { x1: m.l, x2: w - m.r, y1: gy, y2: gy, class: 'rl-chart__grid' }));
			var t = el('text', { x: m.l - 8, y: gy + 4, 'text-anchor': 'end', class: 'rl-chart__ax' });
			t.textContent = gv >= 1000 ? (gv / 1000).toLocaleString('sk-SK') + ' tis.' : String(Math.round(gv));
			svg.appendChild(t);
		}
		pts.forEach(function (p, i) {
			var lx = el('text', { x: x(i), y: h - 10, 'text-anchor': i === 0 && data.length > 1 ? 'start' : i === data.length - 1 && data.length > 1 ? 'end' : 'middle', class: 'rl-chart__ax' });
			lx.textContent = p.label;
			svg.appendChild(lx);
		});

		var d = data.map(function (v, i) { return (i ? 'L' : 'M') + x(i).toFixed(1) + ' ' + y(v).toFixed(1); }).join(' ');
		var base = (h - m.b).toFixed(1);
		svg.appendChild(el('path', { d: d + ' L' + x(data.length - 1).toFixed(1) + ' ' + base + ' L' + x(0).toFixed(1) + ' ' + base + ' Z', class: 'rl-chart__area' }));
		var line = el('path', { d: d, class: 'rl-chart__line' });
		svg.appendChild(line);

		var dots = [];
		data.forEach(function (v, i) {
			var c = el('circle', { cx: x(i), cy: y(v), r: 5, class: 'rl-chart__dot', tabindex: 0, 'aria-label': pts[i].label + ': ' + fmt(v) + ' ' + unit });
			var show = function () {
				dots.forEach(function (o) { o.classList.remove('is-on'); });
				c.classList.add('is-on');
				tip.innerHTML = '<b>' + pts[i].label + '</b><span>' + fmt(v) + ' ' + unit + '</span>';
				tip.hidden = false;
				var tw = tip.offsetWidth;
				var left = Math.min(Math.max(x(i) - tw / 2, 4), w - tw - 4);
				tip.style.left = left + 'px';
				tip.style.top = Math.max(y(v) - tip.offsetHeight - 14, 0) + 'px';
			};
			var hide = function () { c.classList.remove('is-on'); tip.hidden = true; };
			c.addEventListener('mouseenter', show);
			c.addEventListener('focus', show);
			c.addEventListener('mouseleave', hide);
			c.addEventListener('blur', hide);
			c.addEventListener('click', show);
			dots.push(c);
			svg.appendChild(c);
			// väčšia plocha na dotyk
			var hit = el('circle', { cx: x(i), cy: y(v), r: 18, fill: 'transparent' });
			hit.addEventListener('mouseenter', show);
			hit.addEventListener('mouseleave', hide);
			hit.addEventListener('click', show);
			svg.appendChild(hit);
		});
		area.appendChild(svg);

		if (animate && !window.matchMedia('(prefers-reduced-motion: reduce)').matches && line.getTotalLength) {
			var len = line.getTotalLength();
			line.style.strokeDasharray = len;
			line.style.strokeDashoffset = len;
			line.getBoundingClientRect();
			line.style.transition = 'stroke-dashoffset .9s ease';
			line.style.strokeDashoffset = 0;
		}
	}

	root.querySelectorAll('.rl-seg__btn').forEach(function (b) {
		b.addEventListener('click', function () {
			mode = b.getAttribute('data-mode');
			root.querySelectorAll('.rl-seg__btn').forEach(function (o) {
				var on = o === b;
				o.classList.toggle('is-on', on);
				o.setAttribute('aria-pressed', on ? 'true' : 'false');
			});
			tip.hidden = true;
			draw(true);
		});
	});

	if (totalEl) { totalEl.textContent = fmt(pts.reduce(function (s, p) { return s + p.value; }, 0)); }
	var timer;
	window.addEventListener('resize', function () { clearTimeout(timer); timer = setTimeout(function () { draw(false); }, 150); });
	draw(true);
})();

js.cmp-admin.js:
/* Administrácia: spustenie kontroly GDPR lišty AdSense (v skrytom rámci s úvodnou stránkou ako návštevník). */
(function () {
	'use strict';
	var cfg = window.relifeCmp || {};
	var $ = function (id) { return document.getElementById(id); };
	var icon = { ok: '✅', warn: '⚠️', fail: '❌', info: 'ℹ️' };
	var ORDER = ['srv_theme', 'script', 'srv_raw', 'srv_id', 'pub', 'agload', 'fcnet', 'srv_csp', 'srv_fc', 'conflict', 'srv_plugins', 'cookie', 'region', 'fcreq', 'dom', 'tcf'];

	if (cfg.pub && !$('rl-cmp-pub').value) { $('rl-cmp-pub').value = 'ca-pub-' + cfg.pub; }

	function esc(s) { var d = document.createElement('div'); d.textContent = s == null ? '' : String(s); return d.innerHTML; }

	function clearConsent() {
		var names = ['FCCDCF', 'FCNEC', 'euconsent-v2', 'addtl_consent'];
		var host = location.hostname.split('.');
		var domains = ['', location.hostname, '.' + location.hostname];
		if (host.length > 2) { domains.push('.' + host.slice(-2).join('.')); }
		names.forEach(function (n) {
			domains.forEach(function (d) {
				document.cookie = n + '=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/' + (d ? '; domain=' + d : '');
			});
		});
		try { localStorage.removeItem('relife.consent'); } catch (e) { /* nič */ }
	}

	function verdict(res) {
		var byId = {};
		res.forEach(function (r) { byId[r.id] = r; });
		var i, r;
		for (i = 0; i < ORDER.length; i++) {
			r = byId[ORDER[i]];
			if (r && r.status === 'fail') { return { found: true, r: r }; }
		}
		for (i = 0; i < ORDER.length; i++) {
			r = byId[ORDER[i]];
			if (r && r.status === 'warn' && ['conflict', 'cookie', 'region', 'srv_plugins'].indexOf(r.id) > -1) { return { found: true, r: r }; }
		}
		return { found: false };
	}

	function render(res, frameOk) {
		var tb = $('rl-cmp-table').querySelector('tbody');
		tb.innerHTML = '';
		res.sort(function (a, b) {
			var w = { fail: 0, warn: 1, info: 2, ok: 3 };
			return (w[a.status] - w[b.status]);
		});
		res.forEach(function (x) {
			var tr = document.createElement('tr');
			tr.innerHTML = '<td>' + (icon[x.status] || '•') + '</td><td><strong>' + esc(x.title) + '</strong></td><td>' +
				(x.detail ? '<div>' + esc(x.detail) + '</div>' : '') +
				(x.fix && x.status !== 'ok' ? '<div style="color:#1d2327;margin-top:4px"><strong>→ ' + esc(x.fix) + '</strong></div>' : '') + '</td>';
			tb.appendChild(tr);
		});
		$('rl-cmp-table').hidden = false;
		var v = verdict(res);
		var box = $('rl-cmp-verdict');
		box.hidden = false;
		if (v.found) {
			box.style.borderLeftColor = '#d63638';
			box.innerHTML = '<h2 style="margin-top:0">Najpravdepodobnejšia príčina</h2><p style="font-size:15px"><strong>' + esc(v.r.title) + '</strong></p><p>Návrh opravy: ' + esc(v.r.fix) + '</p>';
		} else {
			box.style.borderLeftColor = frameOk ? '#00a32a' : '#dba617';
			box.innerHTML = '<h2 style="margin-top:0">' + (frameOk ? 'Nenašla sa jednoznačná chyba' : 'Test sa dokončil len čiastočne') + '</h2><p>Pozrite upozornenia v tabuľke. Ak lišta stále chýba, otvorte web v novom anonymnom okne zo slovenskej siete.</p>';
		}
		$('rl-cmp-copy').hidden = false;
		$('rl-cmp-copy').onclick = function () {
			var txt = res.map(function (x) { return (icon[x.status] || '•') + ' ' + x.title + (x.detail ? '\n   ' + x.detail : '') + (x.fix && x.status !== 'ok' ? '\n   → ' + x.fix : ''); }).join('\n');
			if (navigator.clipboard) { navigator.clipboard.writeText(txt); $('rl-cmp-copy').textContent = 'Skopírované'; }
		};
	}

	function runFrame(wait) {
		return new Promise(function (resolve) {
			var fr = $('rl-cmp-frame');
			var done = false;
			var finish = function (v) { if (!done) { done = true; resolve(v); } };
			fr.onload = function () {
				setTimeout(function () {
					try {
						var w = fr.contentWindow;
						w.__RELIFE_CMP_NO_AUTORUN = true;
						var s = w.document.createElement('script');
						s.src = cfg.script;
						s.onload = function () {
							w.relifeCmpCheck({ pub: ($('rl-cmp-pub').value || '').replace(/\D/g, '') || cfg.pub }).then(function (r) { finish(r.results); }, function (e) { finish([{ id: 'frame', status: 'fail', title: 'Test v prehliadači zlyhal', detail: String(e), fix: '' }]); });
						};
						s.onerror = function () { finish([{ id: 'frame', status: 'fail', title: 'Nepodarilo sa načítať kontrolný skript', detail: cfg.script, fix: 'Skontrolujte, či je nahraná aktuálna verzia témy.' }]); };
						w.document.head.appendChild(s);
					} catch (e) {
						finish([{ id: 'frame', status: 'fail', title: 'Úvodnú stránku sa nepodarilo otvoriť na kontrolu', detail: String(e), fix: 'Web môže posielať hlavičku X-Frame-Options/CSP frame-ancestors, ktorá zakazuje zobrazenie v rámci. Použite postup z tools/README.md (konzola prehliadača).' }]);
					}
				}, wait * 1000);
			};
			fr.src = cfg.testUrl + '&t=' + Date.now();
			setTimeout(function () { finish([{ id: 'frame', status: 'fail', title: 'Úvodná stránka sa nenačítala včas', detail: '', fix: 'Skúste znova; pri pomalom hostingu zvýšte čakanie.' }]); }, (wait + 40) * 1000);
		});
	}

	$('rl-cmp-run').addEventListener('click', function () {
		var btn = this;
		btn.disabled = true;
		$('rl-cmp-status').textContent = 'Beží test… (približne 20 s)';
		$('rl-cmp-table').hidden = true;
		$('rl-cmp-verdict').hidden = true;
		if ($('rl-cmp-clear').checked) { clearConsent(); }
		var pub = ($('rl-cmp-pub').value || '').replace(/\D/g, '');
		var fd = new FormData();
		fd.append('action', 'relife_cmp');
		fd.append('nonce', cfg.nonce);
		fd.append('pub', pub);
		var server = fetch(cfg.ajax, { method: 'POST', credentials: 'same-origin', body: fd }).then(function (r) { return r.json(); }).then(function (j) { return j.success ? j.data : []; }).catch(function () { return []; });
		Promise.all([server, runFrame(12)]).then(function (all) {
			var frameOk = all[1].length > 0 && all[1][0].id !== 'frame';
			render(all[0].concat(all[1]), frameOk);
			$('rl-cmp-status').textContent = 'Hotovo.';
			btn.disabled = false;
		});
	});
})();

js.cmp-check.js:
/*
 * RELIFE – diagnostika: prečo sa nezobrazuje GDPR lišta (správa o súhlase) z Google AdSense.
 *
 * POUŽITIE (najjednoduchšie): otvorte relife.sk v NOVOM anonymnom okne, počkajte ~10 s, otvorte konzolu
 * (F12 → Console), vložte celý tento súbor a stlačte Enter. Výsledok sa vypíše do konzoly.
 * Alternatíva: node adsense-cmp-check.node.js https://relife.sk   (pozri README.md)
 *
 * Skript nič nemení ani neposiela nikam údaje; len číta stránku a robí jednu požiadavku na ads.txt
 * a na adresu Google Funding Choices.
 */
(function () {
	'use strict';

	var DEFAULT_PUB = '2577354057353027';

	async function relifeCmpCheck(opts) {
		opts = opts || {};
		var pub = String(opts.pub || DEFAULT_PUB).replace(/^ca-/, '').replace(/^pub-/, '');
		var res = [];
		var add = function (id, status, title, detail, fix) {
			res.push({ id: id, status: status, title: title, detail: detail || '', fix: fix || '' });
		};
		var entries = performance.getEntriesByType('resource');
		var has = function (re) { return entries.filter(function (e) { return re.test(e.name); }); };

		/* 1. Je skript AdSense na stránke? */
		var scripts = Array.prototype.slice.call(document.scripts).filter(function (s) { return /adsbygoogle\.js/.test(s.src); });
		var clients = {};
		scripts.forEach(function (s) { var m = /client=(ca-pub-\d+)/.exec(s.src); if (m) { clients[m[1]] = 1; } });
		Array.prototype.slice.call(document.querySelectorAll('ins.adsbygoogle[data-ad-client]')).forEach(function (n) { clients[n.getAttribute('data-ad-client')] = 1; });
		var clientList = Object.keys(clients);
		var loaderInline = /pagead2\.googlesyndication\.com\/pagead\/js\/adsbygoogle\.js/.test(document.documentElement.innerHTML);

		if (!scripts.length && !loaderInline) {
			add('script', 'fail', 'Skript AdSense (adsbygoogle.js) na stránke nie je',
				'Bez neho Google nemá čo načítať, preto sa nezobrazí ani lišta súhlasu.',
				'1) Vzhľad → Prispôsobiť → RELIFE – Reklamy: vyplňte ID vydavateľa alebo vložte celý kód AdSense do hlavičky (téma ho načíta po načítaní stránky). 2) Vyprázdnite cache (Starcache). 3) Skontrolujte, či nie ste prihlásený ako redaktor, ak je zapnuté „Neukazovať reklamy prihláseným redaktorom“. 4) Pri článku nesmie byť zapnuté „Nezobrazovať reklamy v tomto článku“.');
		} else {
			add('script', 'ok', 'Skript AdSense je na stránke', scripts.length ? scripts[0].src : '(vkladá sa dynamicky po načítaní stránky)');
		}

		/* 2. Zhoduje sa ID vydavateľa? */
		if (clientList.length) {
			if (clientList.indexOf('ca-pub-' + pub) === -1) {
				add('pub', 'fail', 'ID vydavateľa na stránke nie je ca-pub-' + pub, 'Nájdené: ' + clientList.join(', '),
					'Opravte ID v Customizeri alebo v kóde AdSense. Lištu GDPR zobrazuje len správa priradená k tomu istému účtu.');
			} else if (clientList.length > 1) {
				add('pub', 'warn', 'Na stránke je viac ID vydavateľov', clientList.join(', '), 'Ponechajte len jedno ID – rôzne kódy sa môžu rušiť.');
			} else {
				add('pub', 'ok', 'ID vydavateľa sedí', 'ca-pub-' + pub);
			}
		}

		/* 3. Načítal sa adsbygoogle.js? */
		var ag = has(/adsbygoogle\.js/);
		var agLoaded = !!(window.adsbygoogle && window.adsbygoogle.loaded === true);
		if ((scripts.length || loaderInline) && !ag.length && !agLoaded) {
			add('agload', 'fail', 'Skript AdSense sa nestiahol (zablokovaný alebo ešte nenačítaný)', 'V sieťových požiadavkách nie je žiadny záznam pre adsbygoogle.js.',
				'Počkajte ~10 s po načítaní stránky a spustite kontrolu znova. Ak sa nestiahne: vypnite blokovač reklám/ochranu súkromia v prehliadači, skontrolujte CSP hlavičku servera (musí povoliť pagead2.googlesyndication.com a fundingchoicesmessages.google.com).');
		} else if (ag.length || agLoaded) {
			add('agload', 'ok', 'Skript AdSense sa načítal', ag.length ? ag[0].name : 'window.adsbygoogle.loaded = true');
		}

		/* 4. Požiadavka na Funding Choices (tadiaľ prichádza GDPR správa) */
		var fc = has(/fundingchoicesmessages\.google\.com/);
		var probe = 'nezistené';
		try {
			await fetch('https://fundingchoicesmessages.google.com/i/pub-' + pub + '?ers=1', { mode: 'no-cors', cache: 'no-store' });
			probe = 'dostupné';
		} catch (e) {
			probe = 'zablokované / chyba siete';
		}
		if (probe !== 'dostupné') {
			add('fcnet', 'fail', 'Adresa Google Funding Choices je z tohto prehliadača nedostupná', 'fundingchoicesmessages.google.com → ' + probe,
				'Vypnite blokovač reklám / ochranu proti sledovaniu / DNS filter (AdGuard, uBlock, Pi-hole, Brave Shields) a skúste znova v čistom anonymnom okne.');
		}
		if (!fc.length) {
			add('fcreq', (scripts.length || agLoaded) ? 'fail' : 'warn', 'Stránka si nevyžiadala GDPR správu od Google',
				'AdSense skript sa pri načítaní neobrátil na fundingchoicesmessages.google.com. Skript to robí len vtedy, keď má účet publikovanú správu pre túto stránku.',
				'V AdSense: Súkromie a správy (Privacy & messaging) → Európske predpisy (GDPR) → vytvorte správu a stlačte „Publikovať“. Skontrolujte, že je v zozname „Stránky“ a že relife.sk má stav Pripravené (overená stránka). Po publikovaní počkajte 1–2 hodiny.');
		} else {
			add('fcreq', 'ok', 'Stránka si vyžiadala GDPR správu od Google', fc[0].name);
		}

		/* 5. Je správa v DOM? */
		var dialog = document.querySelector('.fc-consent-root, .fc-dialog-container, .fc-dialog-overlay');
		var present = document.querySelector('iframe[name="googlefcPresent"]');
		var inactive = document.querySelector('iframe[name="googlefcInactive"]');
		var visible = false;
		if (dialog) {
			var r = dialog.getBoundingClientRect();
			var cs = getComputedStyle(dialog);
			visible = r.width > 0 && r.height > 0 && cs.visibility !== 'hidden' && cs.display !== 'none';
		}
		if (dialog && visible) {
			add('dom', 'ok', 'GDPR lišta Google je na stránke a je viditeľná');
		} else if (dialog && !visible) {
			add('dom', 'fail', 'GDPR lišta Google je v stránke, ale je skrytá', 'Prvok existuje, ale nie je vidieť (display/visibility/rozmery).',
				'Pravdepodobne ju prekrýva alebo skrýva CSS témy/pluginu (z-index, overflow, display:none). Vyskúšajte dočasne vypnúť pluginy na optimalizáciu CSS/JS (minifikácia, odkladanie skriptov).');
		} else if (inactive) {
			add('dom', 'fail', 'Google hlási „žiadna aktívna správa“ (googlefcInactive)', 'Skript Funding Choices sa načítal, ale pre túto stránku/návštevníka sa žiadna správa nemá zobraziť.',
				'Najčastejšie: správa nie je publikovaná alebo nie je priradená k relife.sk, návštevník nie je v EHP/UK, alebo už súhlas dal (cookie FCCDCF). Skontrolujte v AdSense → Súkromie a správy, či je GDPR správa „Aktívna“ a obsahuje relife.sk.');
		} else if (present) {
			add('dom', 'warn', 'Funding Choices je prítomný, ale lišta sa nezobrazila', 'Iframe googlefcPresent existuje, dialóg nie.', 'Súhlas bol pravdepodobne už zadaný (pozrite cookies), alebo správa čaká na publikovanie.');
		} else {
			add('dom', 'fail', 'V stránke nie je žiadny prvok Google Funding Choices', 'Neexistuje ani dialóg, ani iframe googlefcPresent/googlefcInactive.',
				'Pozri vyššie: skript sa buď nenačítal, alebo účet nemá publikovanú správu pre túto stránku.');
		}

		/* 6. TCF API (štandardné rozhranie lišty) */
		if (typeof window.__tcfapi === 'function') {
			var tc = await new Promise(function (resolve) {
				var done = false;
				var t = setTimeout(function () { if (!done) { done = true; resolve(null); } }, 3000);
				try {
					window.__tcfapi('getTCData', 2, function (d, ok) { if (!done) { done = true; clearTimeout(t); resolve(ok ? d : { error: true }); } });
				} catch (e) { if (!done) { done = true; clearTimeout(t); resolve(null); } }
			});
			if (!tc) {
				add('tcf', 'warn', 'Rozhranie TCF (__tcfapi) existuje, ale neodpovedá', '', 'Skúste stránku znova načítať; ak sa opakuje, koliduje druhá cookie lišta.');
			} else {
				var d = 'gdprApplies=' + tc.gdprApplies + ', cmpStatus=' + tc.cmpStatus + ', eventStatus=' + tc.eventStatus + ', tcString=' + (tc.tcString ? tc.tcString.length + ' znakov' : 'prázdny');
				if (tc.gdprApplies === false) {
					add('tcf', 'warn', 'TCF hovorí, že GDPR sa na vás nevzťahuje (gdprApplies=false)', d,
						'Google zobrazuje lištu len návštevníkom z EHP/UK/Švajčiarska. Testujte zo slovenskej IP (nie cez VPN mimo EÚ).');
				} else {
					add('tcf', 'ok', 'Rozhranie TCF funguje', d);
				}
			}
		} else {
			add('tcf', 'info', 'Rozhranie TCF (__tcfapi) na stránke nie je', 'Žiadna certifikovaná lišta (CMP) sa zatiaľ nezaregistrovala.');
		}

		/* 7. Už zadaný súhlas? */
		var ck = document.cookie.split(';').map(function (c) { return c.trim().split('=')[0]; });
		var consentCookies = ck.filter(function (n) { return /^(FCCDCF|FCNEC|euconsent-v2|addtl_consent)$/.test(n); });
		if (consentCookies.length) {
			add('cookie', 'warn', 'Súhlas už bol zadaný (cookies: ' + consentCookies.join(', ') + ')', 'Lišta sa druhýkrát nezobrazí.',
				'Test urobte v novom anonymnom okne alebo vymažte tieto cookies pre relife.sk (F12 → Application → Cookies).');
		} else {
			add('cookie', 'ok', 'Žiadny uložený súhlas Google – lišta by sa mala ukázať');
		}

		/* 8. Konflikt s inou lištou */
		var others = [];
		var gl = { Cookiebot: window.Cookiebot, OneTrust: window.OneTrust, CookieYes: window.cookieyes || window.CookieYes, Complianz: window.cmplz_blocked_scripts || window.complianz, Usercentrics: window.UC_UI, 'Borlabs Cookie': window.BorlabsCookie, 'CookieConsent': window.CookieConsent, Iubenda: window._iub, Didomi: window.Didomi, Termly: window.Termly };
		Object.keys(gl).forEach(function (k) { if (gl[k]) { others.push(k); } });
		if (document.querySelector('[id*="cookie-law-info"], [class*="cmplz"], #cookiebanner, .cc-window')) { others.push('iná cookie lišta v DOM'); }
		if (others.length) {
			add('conflict', 'warn', 'Na stránke je iná cookie lišta: ' + others.join(', '), 'Dve lišty sa rušia; Google nezobrazí svoju správu, ak už existuje iná TCF lišta.',
				'Používajte jednu: buď vypnite druhý plugin, alebo v ňom nastavte Google ako CMP.');
		}
		if (document.getElementById('rl-cookie')) {
			add('rlbanner', 'warn', 'Zobrazuje sa aj vlastná lišta témy RELIFE (#rl-cookie)', 'Okrem Google lišty je zapnutá aj lišta témy pre Google Analytics.',
				'Ak chcete len Google lištu: Vzhľad → Prispôsobiť → RELIFE → vypnite „Zobraziť cookie lištu“ a nechajte meranie riadiť Googlom.');
		}

		/* 9. ads.txt */
		try {
			var t = await fetch('/ads.txt', { cache: 'no-store' });
			var txt = t.ok ? await t.text() : '';
			if (!t.ok) {
				add('adstxt', 'warn', 'ads.txt neexistuje (' + t.status + ')', '', 'Pridajte riadok „google.com, pub-' + pub + ', DIRECT, f08c47fec0942fa0“ (téma ho vytvorí sama, ak je zadané ID v Customizeri) – chýbajúci ads.txt znižuje príjmy a AdSense na to upozorňuje.');
			} else if (txt.indexOf('pub-' + pub) === -1) {
				add('adstxt', 'warn', 'ads.txt neobsahuje pub-' + pub, txt.slice(0, 200), 'Doplňte riadok „google.com, pub-' + pub + ', DIRECT, f08c47fec0942fa0“.');
			} else {
				add('adstxt', 'ok', 'ads.txt obsahuje vaše ID');
			}
		} catch (e) {
			add('adstxt', 'info', 'ads.txt sa nepodarilo načítať', String(e));
		}

		/* 10. Okolnosti testu */
		if (document.getElementById('wpadminbar')) {
			add('admin', 'warn', 'Ste prihlásený vo WordPresse (admin lišta)', '', 'Téma pre prihlásených redaktorov môže skrývať reklamy/tag. Testujte odhlásený alebo v anonymnom okne.');
		}
		var tz = '';
		try { tz = Intl.DateTimeFormat().resolvedOptions().timeZone || ''; } catch (e) { /* nič */ }
		if (tz && !/^(Europe|Atlantic\/(Reykjavik|Canary|Madeira|Azores)|Africa\/Ceuta)/.test(tz)) {
			add('region', 'warn', 'Časové pásmo prehliadača (' + tz + ') nie je európske', '', 'GDPR správu vidia len návštevníci z EHP/UK/CH. Testujte zo slovenskej siete bez VPN.');
		}

		return { url: location.href, pub: 'ca-pub-' + pub, when: new Date().toISOString(), results: res, verdict: verdict(res) };
	}

	/* Vyhodnotenie: najpravdepodobnejšia príčina a postup opravy */
	function verdict(res) {
		var order = ['script', 'pub', 'agload', 'fcnet', 'conflict', 'cookie', 'region', 'admin', 'fcreq', 'dom', 'tcf', 'rlbanner'];
		var byId = {};
		res.forEach(function (r) { byId[r.id] = r; });
		for (var i = 0; i < order.length; i++) {
			var r = byId[order[i]];
			if (r && (r.status === 'fail' || (r.status === 'warn' && ['conflict', 'cookie', 'region', 'admin'].indexOf(r.id) > -1))) {
				return { found: true, id: r.id, title: r.title, fix: r.fix };
			}
		}
		var allOk = res.every(function (r) { return r.status === 'ok' || r.status === 'info' || r.id === 'adstxt'; });
		return allOk ? { found: false, title: 'Všetko vyzerá v poriadku – lišta by sa mala zobrazovať.', fix: '' } : { found: false, title: 'Jednoznačná chyba sa nenašla, pozrite upozornenia vyššie.', fix: '' };
	}

	function relifeCmpFormat(r) {
		var icon = { ok: '✅', warn: '⚠️ ', fail: '❌', info: 'ℹ️ ' };
		var out = [];
		out.push('RELIFE – kontrola GDPR lišty AdSense');
		out.push(r.url + '  |  ' + r.pub + '  |  ' + r.when);
		out.push('');
		r.results.forEach(function (x) {
			out.push((icon[x.status] || '•') + ' ' + x.title);
			if (x.detail) { out.push('     ' + x.detail); }
			if (x.fix && x.status !== 'ok') { out.push('     → ' + x.fix); }
		});
		out.push('');
		out.push('VÝSLEDOK: ' + r.verdict.title);
		if (r.verdict.fix) { out.push('NÁVRH OPRAVY: ' + r.verdict.fix); }
		return out.join('\n');
	}

	window.relifeCmpCheck = relifeCmpCheck;
	window.relifeCmpFormat = relifeCmpFormat;

	if (!window.__RELIFE_CMP_NO_AUTORUN) {
		relifeCmpCheck().then(function (r) {
			window.__relifeCmpResult = r;
			console.log(relifeCmpFormat(r));
		});
	}
})();

js.relife.js:
/**
 * RELIFE – interakcie v prehliadači čitateľa.
 * Všetko (hlas v ankete, nálada, uložené články) sa ukladá len lokálne:
 *   localStorage: relife.vote.<id>, relife.mood, relife.saved
 *   Cache API:    relife-saved-v1 (kópia uložených stránok pre offline)
 */
( function () {
	'use strict';

	var data = window.relifeData || {};
	var i18n = data.i18n || {};
	var CACHE = 'relife-saved-v1';

	function lsGet( key, fallback ) {
		try {
			var v = window.localStorage.getItem( key );
			return v === null ? fallback : v;
		} catch ( e ) {
			return fallback;
		}
	}
	function lsSet( key, value ) {
		try {
			window.localStorage.setItem( key, value );
		} catch ( e ) { /* súkromný režim */ }
	}
	/** Odošle udalosť do Google tagu (ak je načítaný). Meno a parametre neobsahujú osobné údaje. */
	function track( name, params ) {
		try {
			if ( typeof window.gtag === 'function' ) { window.gtag( 'event', name, params || {} ); }
		} catch ( e ) { /* sledovanie nesmie ovplyvniť stránku */ }
	}
	function qs( sel, root ) { return ( root || document ).querySelector( sel ); }
	function qsa( sel, root ) { return Array.prototype.slice.call( ( root || document ).querySelectorAll( sel ) ); }

	/* ---------- Uložené články ---------- */
	function getSaved() {
		try {
			var arr = JSON.parse( lsGet( 'relife.saved', '[]' ) );
			return Array.isArray( arr ) ? arr.map( Number ) : [];
		} catch ( e ) {
			return [];
		}
	}
	function setSaved( list ) {
		lsSet( 'relife.saved', JSON.stringify( list ) );
		updateSavedUI();
	}
	function cacheUrl( url, add ) {
		if ( ! window.caches || ! url ) { return; }
		window.caches.open( CACHE ).then( function ( cache ) {
			return add ? cache.add( url ) : cache.delete( url );
		} ).catch( function () {} );
	}
	function updateSavedUI() {
		var saved = getSaved();
		qsa( '.js-saved-count' ).forEach( function ( el ) { el.textContent = String( saved.length ); } );
		qsa( '.js-save' ).forEach( function ( btn ) {
			var on = saved.indexOf( Number( btn.getAttribute( 'data-id' ) ) ) !== -1;
			btn.setAttribute( 'aria-pressed', on ? 'true' : 'false' );
			btn.setAttribute( 'aria-label', on ? ( i18n.unsave || 'Odstrániť z uložených' ) : ( i18n.save || 'Uložiť článok' ) );
		} );
	}
	/* Anonymné počítadlo uložení pre štatistiku v administrácii: len ID článku a smer, bez osobných údajov. */
	function countSave( id, action ) {
		if ( ! data.saveUrl || ! window.fetch ) { return; }
		try {
			fetch( data.saveUrl, {
				method: 'POST',
				headers: { 'Content-Type': 'application/json' },
				body: JSON.stringify( { id: id, action: action } ),
				keepalive: true,
				credentials: 'omit'
			} ).catch( function () {} );
		} catch ( e ) { /* nič */ }
	}
	document.addEventListener( 'click', function ( ev ) {
		var btn = ev.target.closest ? ev.target.closest( '.js-save' ) : null;
		if ( ! btn ) { return; }
		ev.preventDefault();
		var id = Number( btn.getAttribute( 'data-id' ) );
		var url = btn.getAttribute( 'data-url' );
		var saved = getSaved();
		var idx = saved.indexOf( id );
		if ( idx === -1 ) {
			saved.push( id );
			cacheUrl( url, true );
			track( 'relife_save_article', { article_id: id } );
			countSave( id, 'save' );
		} else {
			saved.splice( idx, 1 );
			cacheUrl( url, false );
			countSave( id, 'unsave' );
		}
		setSaved( saved );
		if ( qs( '.js-saved-list' ) ) { renderSavedPage(); }
	} );

	function esc( s ) {
		var d = document.createElement( 'div' );
		d.textContent = s == null ? '' : String( s );
		return d.innerHTML;
	}
	function renderSavedPage() {
		var list = qs( '.js-saved-list' );
		var empty = qs( '.js-saved-empty' );
		if ( ! list ) { return; }
		var ids = getSaved();
		if ( ! ids.length ) {
			list.innerHTML = '';
			if ( empty ) { empty.hidden = false; }
			return;
		}
		if ( empty ) { empty.hidden = true; }
		var url = data.restUrl + ( data.restUrl.indexOf( '?' ) === -1 ? '?' : '&' ) + 'include=' + ids.join( ',' ) + '&per_page=50&_fields=id,link,title,relife';
		window.fetch( url ).then( function ( r ) { return r.json(); } ).then( function ( posts ) {
			var byId = {};
			( posts || [] ).forEach( function ( p ) { byId[ p.id ] = p; } );
			list.innerHTML = ids.map( function ( id ) {
				var p = byId[ id ];
				if ( ! p ) { return ''; }
				var r = p.relife || {};
				var title = p.title && p.title.rendered ? p.title.rendered : '';
				var media = r.thumbnail ? '<img src="' + esc( r.thumbnail ) + '" alt="" loading="lazy">' : '<span class="rl-card__initial" aria-hidden="true">' + esc( ( r.section || '' ).charAt( 0 ) ) + '</span>';
				return '<div class="rl-card js-card" data-id="' + id + '"><a class="rl-card__link" href="' + esc( p.link ) + '">' +
					'<span class="rl-card__media" style="background:' + esc( r.color || '#3CFFD0' ) + '">' + media + '<span class="rl-tag rl-tag--dark">' + esc( r.section ) + '</span></span>' +
					'<h3 class="rl-card__title">' + title + '</h3>' +
					'<span class="rl-meta">' + esc( ( r.format ? r.format + ' · ' : '' ) + ( r.readTime || 1 ) + ' min' ) + '</span></a>' +
					'<button type="button" class="rl-save js-save" data-id="' + id + '" data-url="' + esc( p.link ) + '" aria-pressed="true" aria-label="' + esc( i18n.unsave ) + '">' +
					'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linejoin="round" aria-hidden="true"><path d="M6 3h12v18l-6-4-6 4z"/></svg></button></div>';
			} ).join( '' );
			if ( empty && ! list.children.length ) { empty.hidden = false; }
		} ).catch( function () { if ( empty ) { empty.hidden = false; } } );
	}

	/* ---------- Anketa ---------- */
	function initPoll() {
		var poll = qs( '.js-poll' );
		if ( ! poll ) { return; }
		var key = 'relife.vote.' + poll.getAttribute( 'data-poll' );
		var opts = qsa( '.js-opt', poll );
		var note = qs( '.js-poll-note', poll );

		function show( voted, mine ) {
			poll.classList.toggle( 'is-voted', voted );
			opts.forEach( function ( o, i ) {
				var pct = Number( o.getAttribute( 'data-pct' ) ) || 0;
				var on = voted && i === mine;
				o.classList.toggle( 'is-mine', on );
				o.setAttribute( 'aria-pressed', on ? 'true' : 'false' );
				qs( '.js-pct', o ).textContent = voted ? pct + ' %' : '';
				qs( '.js-bar', o ).style.width = voted ? pct + '%' : '0%';
			} );
			if ( note ) { note.textContent = voted ? ( i18n.thanks || '' ) : ( i18n.beforeVote || '' ); }
		}

		var stored = lsGet( key, '' );
		var mine = stored === '' ? -1 : parseInt( stored, 10 );
		show( mine >= 0, mine );

		opts.forEach( function ( o, i ) {
			o.addEventListener( 'click', function () {
				if ( poll.classList.contains( 'is-voted' ) ) { return; }
				lsSet( key, String( i ) );
				show( true, i );
				track( 'relife_poll_vote', { poll_id: poll.getAttribute( 'data-poll' ), option_index: i } );
			} );
		} );
	}

	/* ---------- Karta: anketa / nálada ---------- */
	function initSidecard() {
		var card = qs( '.js-sidecard' );
		if ( ! card ) { return; }
		var tabPoll = qs( '.js-tab-poll', card );
		var tabMood = qs( '.js-tab-mood', card );
		var pPoll = qs( '.js-panel-poll', card );
		var pMood = qs( '.js-panel-mood', card );
		function tab( mood ) {
			pPoll.hidden = mood;
			pMood.hidden = ! mood;
			tabPoll.classList.toggle( 'is-active', ! mood );
			tabMood.classList.toggle( 'is-active', mood );
			tabPoll.setAttribute( 'aria-selected', mood ? 'false' : 'true' );
			tabMood.setAttribute( 'aria-selected', mood ? 'true' : 'false' );
		}
		tabPoll.addEventListener( 'click', function () { tab( false ); } );
		tabMood.addEventListener( 'click', function () { tab( true ); } );
	}

	/* ---------- Nálada: filtrovanie článkov na úvodnej stránke ---------- */
	function initMood() {
		var grid = qs( '.js-today' );
		var moodBtns = qsa( '.js-mood' );
		if ( ! grid || ! moodBtns.length ) { return; }
		var limit = Number( grid.getAttribute( 'data-limit' ) ) || 4;
		var titleEl = qs( '.js-today-title' );
		var status = qs( '.js-mood-status' );
		var statusText = qs( '.js-mood-text' );
		var emptyEl = qs( '.js-today-empty' );
		var moods = data.moods || [];

		function apply( id ) {
			var mood = moods.filter( function ( m ) { return m.id === id; } )[ 0 ] || null;
			var shown = 0;
			qsa( '.js-card', grid ).forEach( function ( card ) {
				var secs = ( card.getAttribute( 'data-sections' ) || '' ).split( ' ' );
				var match = ! mood || mood.sections.some( function ( s ) { return secs.indexOf( s ) !== -1; } );
				var visible = match && shown < limit;
				if ( visible ) { shown++; }
				card.classList.toggle( 'is-hidden', ! visible );
			} );
			moodBtns.forEach( function ( b ) { b.setAttribute( 'aria-pressed', mood && b.getAttribute( 'data-mood' ) === mood.id ? 'true' : 'false' ); } );
			if ( titleEl ) { titleEl.textContent = mood ? ( titleEl.getAttribute( 'data-mood' ) || 'Pre tvoju náladu' ) : titleEl.getAttribute( 'data-default' ); }
			if ( status ) {
				status.hidden = ! mood;
				if ( mood && statusText ) { statusText.innerHTML = ( i18n.moodNow || '' ) + ' <b>' + esc( mood.label ) + '</b> · ' + esc( mood.sections.join( ' · ' ).toUpperCase() ); }
			}
			if ( emptyEl ) {
				emptyEl.hidden = shown > 0;
				emptyEl.textContent = shown > 0 ? '' : ( i18n.moodNone || '' );
			}
		}

		var current = lsGet( 'relife.mood', '' ) || null;
		apply( current );
		moodBtns.forEach( function ( b ) {
			b.addEventListener( 'click', function () {
				var id = b.getAttribute( 'data-mood' );
				current = current === id ? null : id;
				lsSet( 'relife.mood', current || '' );
				apply( current );
				if ( current ) { track( 'relife_mood_select', { mood: current } ); }
			} );
		} );
		var clear = qs( '.js-mood-clear' );
		if ( clear ) {
			clear.addEventListener( 'click', function () {
				current = null;
				lsSet( 'relife.mood', '' );
				apply( null );
			} );
		}
	}

	/* ---------- Filter starších ankiet ---------- */
	function initPollFilters() {
		var wrap = qs( '.js-poll-filters' );
		if ( ! wrap ) { return; }
		wrap.addEventListener( 'click', function ( ev ) {
			var b = ev.target.closest ? ev.target.closest( '.rl-filter' ) : null;
			if ( ! b ) { return; }
			var f = b.getAttribute( 'data-filter' );
			qsa( '.rl-filter', wrap ).forEach( function ( x ) {
				var on = x === b;
				x.classList.toggle( 'is-active', on );
				x.setAttribute( 'aria-pressed', on ? 'true' : 'false' );
			} );
			qsa( '.js-pollcard' ).forEach( function ( c ) {
				c.classList.toggle( 'is-hidden', f !== 'all' && c.getAttribute( 'data-section' ) !== f );
			} );
		} );
	}

	/* ---------- Hľadanie, zdieľanie, progres, spodné menu ---------- */
	function initMisc() {
		var panel = qs( '#rl-search' );
		qsa( '.js-search-toggle' ).forEach( function ( btn ) {
			btn.addEventListener( 'click', function () {
				if ( ! panel ) { return; }
				var mp = qs( '#rl-menu' ), mb = qs( '.js-menu-toggle' );
				if ( mp && ! mp.hidden && mb ) { mb.click(); }
				var open = panel.hidden;
				panel.hidden = ! open;
				qsa( '.js-search-toggle' ).forEach( function ( b ) { b.setAttribute( 'aria-expanded', open ? 'true' : 'false' ); } );
				if ( open ) {
					var input = qs( 'input[type="search"]', panel );
					if ( input ) { input.focus(); window.scrollTo( { top: 0, behavior: 'smooth' } ); }
				}
			} );
		} );

		qsa( '.js-share' ).forEach( function ( btn ) {
			btn.addEventListener( 'click', function () {
				var payload = { title: btn.getAttribute( 'data-title' ), url: btn.getAttribute( 'data-url' ) };
				if ( navigator.share ) {
					navigator.share( payload ).catch( function () {} );
				} else if ( navigator.clipboard ) {
					navigator.clipboard.writeText( payload.url ).then( function () { btn.textContent = 'Odkaz skopírovaný'; } );
				}
			} );
		} );

		var bar = qs( '.js-progress' );
		var art = qs( '.rl-article__main' );
		if ( bar && art ) {
			var onScroll = function () {
				var r = art.getBoundingClientRect();
				var total = r.height - window.innerHeight * 0.5;
				var pct = Math.min( 100, Math.max( 0, ( -r.top + window.innerHeight * 0.3 ) / total * 100 ) );
				bar.style.width = pct + '%';
			};
			window.addEventListener( 'scroll', onScroll, { passive: true } );
			onScroll();
		}

		/* Plávajúca výzva na ďalší článok: len na mobile, v poslednej tretine čítania článku. */
		var next = qs( '.js-next' );
		var body = qs( '.rl-content' );
		if ( next && body && window.matchMedia ) {
			var mq = window.matchMedia( '(max-width: 760px)' );
			var nkey = 'relife.next.' + next.getAttribute( 'data-post' );
			var closed = false;
			try { closed = window.sessionStorage.getItem( nkey ) === '1'; } catch ( e ) { /* nič */ }
			var shown = false;
			var footer = qs( '.rl-footer' );
			var setNext = function ( on ) {
				if ( on === shown ) { return; }
				shown = on;
				if ( on ) {
					next.hidden = false;
					window.requestAnimationFrame( function () { next.classList.add( 'is-on' ); } );
					track( 'relife_next_shown', { article_id: Number( next.getAttribute( 'data-post' ) ) } );
				} else {
					next.classList.remove( 'is-on' );
					window.setTimeout( function () { if ( ! shown ) { next.hidden = true; } }, 260 );
				}
			};
			var checkNext = function () {
				if ( closed || ! mq.matches ) { setNext( false ); return; }
				var r = body.getBoundingClientRect();
				var vh = window.innerHeight;
				var progress = ( vh - r.top ) / r.height; /* kam až v texte siaha spodok obrazovky */
				var footerVisible = footer && footer.getBoundingClientRect().top < vh;
				setNext( progress >= 0.66 && ! footerVisible );
			};
			window.addEventListener( 'scroll', checkNext, { passive: true } );
			window.addEventListener( 'resize', checkNext );
			next.addEventListener( 'click', function ( ev ) {
				if ( ev.target.closest && ev.target.closest( '.js-next-close' ) ) {
					closed = true;
					try { window.sessionStorage.setItem( nkey, '1' ); } catch ( e ) { /* nič */ }
					setNext( false );
				} else if ( ev.target.closest && ev.target.closest( '.rl-next__link' ) ) {
					track( 'relife_next_click', { article_id: Number( next.getAttribute( 'data-post' ) ) } );
				}
			} );
			checkNext();
		}

		var cls = document.body.classList;
		qsa( '.js-tab' ).forEach( function ( a ) {
			var m = a.getAttribute( 'data-match' );
			var active = ( 'home' === m && cls.contains( 'home' ) ) || ( 'saved' === m && cls.contains( 'page-template-template-saved' ) );
			a.classList.toggle( 'is-active', active );
		} );
	}

	/* ---------- Rozbaľovacie menu Sekcie (mobil) ---------- */
	function initMenu() {
		var btn = qs( '.js-menu-toggle' );
		var panel = qs( '#rl-menu' );
		if ( ! btn || ! panel ) { return; }
		function setOpen( open ) {
			panel.hidden = ! open;
			btn.setAttribute( 'aria-expanded', open ? 'true' : 'false' );
			btn.classList.toggle( 'is-active', open );
			btn.setAttribute( 'aria-label', btn.getAttribute( open ? 'data-open-label' : 'data-closed-label' ) || '' );
			document.documentElement.classList.toggle( 'rl-lock', open );
			if ( open ) { panel.scrollTop = 0; }
		}
		btn.addEventListener( 'click', function () { setOpen( panel.hidden ); } );
		panel.addEventListener( 'click', function ( ev ) {
			if ( ev.target.closest && ev.target.closest( 'a' ) ) { setOpen( false ); }
		} );
		document.addEventListener( 'keydown', function ( ev ) {
			if ( ev.key === 'Escape' && ! panel.hidden ) { setOpen( false ); btn.focus(); }
		} );
		window.addEventListener( 'resize', function () {
			if ( window.innerWidth > 760 && ! panel.hidden ) { setOpen( false ); }
		} );
	}

	function init() {
		updateSavedUI();
		initPoll();
		initSidecard();
		initMood();
		initPollFilters();
		initMisc();
		initMenu();
		renderSavedPage();
		document.documentElement.classList.add( 'rl-ready' );
	}
	if ( document.readyState === 'loading' ) {
		document.addEventListener( 'DOMContentLoaded', init );
	} else {
		init();
	}
}() );

assets.lacne-letenky.css:
/* Lacné letenky – plugin. Všetko je pod triedou .ll, aby sa neklialo so stránkou.
   Blok nemá vlastné pozadie – prevezme pozadie sekcie, do ktorej ho vložíte. */
.ll {
  /* RELIFE: tmavý dizajn, akcent a písma z témy */
  --ll-bg: #131313;
  --ll-surface: #1F1F1F;
  --ll-ink: #F5F5F2;
  --ll-ink-2: #A6A6A6;
  --ll-line: #3D3D3D;
  --ll-soft: #2A2A2A;
  --ll-card: #1F1F1F;
  --ll-card-hover: #262626;
  --ll-feature: linear-gradient(135deg, #5200FF 0%, #2B0A8C 100%);
  --ll-feature-ink: #ffffff;
  --ll-feature-ink-2: #D4C8FF;
  --ll-accent: #3CFFD0;
  --ll-accent-soft: rgba(60, 255, 208, .12);
  --ll-good: #A6FF4D;
  --ll-good-soft: rgba(166, 255, 77, .14);
  --ll-warn: #FFE14D;
  --ll-shadow: 0 1px 2px rgba(0, 0, 0, .3);
  --ll-shadow-hi: 0 14px 34px -12px rgba(0, 0, 0, .7), 0 2px 6px rgba(0, 0, 0, .3);
  --ll-font: var(--rl-body, "Inter", system-ui, -apple-system, "Segoe UI", sans-serif);
  --ll-head: var(--rl-display, "Bricolage Grotesque", "Inter", system-ui, sans-serif);
  --ll-mono: ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
  color-scheme: dark;

  --ll-gap: clamp(10px, 0.5rem + 0.8vw, 16px);
  color: var(--ll-ink);
  font-family: var(--ll-font);
  font-size: 15px;
  line-height: 1.45;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(16px, 0.75rem + 1.2vw, 24px);
  font-variant-numeric: tabular-nums;
}
.ll *, .ll *::before, .ll *::after { box-sizing: border-box; }
.ll :focus-visible { outline: 2px solid var(--ll-accent); outline-offset: 3px; }
.ll p { margin: 0; }

/* Písmo z témy webu (WordPress: nastavenie „Písmo: podľa témy“).
   Mení sa len rodina písma – veľkosti a hrúbky ostávajú. Kódy letísk ostávajú v strojovom písme. */
.ll.ll-inherit-font { font-family: inherit; }
.ll.ll-inherit-font *:not(.ll-route):not(.ll-route *) { font-family: inherit !important; }

/* Poistky proti štýlom tém (napr. Newspaper od tagDiv): zoznamy, odkazy, nadpisy, odstavce. */
.ll.ll ul, .ll.ll li { margin: 0; padding: 0; list-style: none; background: none; }
.ll.ll li::before { content: none; }
.ll.ll a, .ll.ll a:hover, .ll.ll a:focus { text-decoration: none; }
.ll.ll p { margin: 0; padding: 0; line-height: inherit; }
.ll.ll h2, .ll.ll h3 { margin: 0; padding: 0; border: 0; text-transform: none; background: none; }
.ll.ll button { margin: 0; line-height: 1; text-transform: none; letter-spacing: 0; min-height: 0; height: auto; }
.ll.ll svg { display: inline-block; }

/* ---------- hlavička ---------- */
.ll.ll .ll-title { margin: 6px 0 0; font: 700 clamp(24px, 3.4vw, 34px)/1.12 var(--ll-font); letter-spacing: -.02em; text-wrap: balance; }

/* ---------- karty ---------- */
.ll-rail { position: relative; container-type: inline-size; }
/* okraje pásu miznú do pozadia – naznačujú, že sa dá posúvať */
.ll-rail::after {
  content: ""; position: absolute; top: 0; bottom: 28px; right: 0; width: 28px; pointer-events: none;
  background: linear-gradient(90deg, transparent, var(--ll-bg)); opacity: .95;
}
.ll-rail.is-end::after { opacity: 0; }
/* posuvný pás na všetkých šírkach: naraz vidno 1,5 karty (polovica ďalšej naznačuje posúvanie) */
.ll.ll .ll-grid {
  /* vnútorný okraj: tieň a nadvihnutie karty pri hover sa zmestia do pásu (inak by ich orezal) */
  list-style: none; margin: 0; padding: 10px 16px 28px; scroll-padding-inline: 16px; display: grid; gap: var(--ll-gap);
  grid-auto-flow: column; grid-auto-columns: calc((100% + 16px - var(--ll-gap)) / 1.5); /* 1,5 karty vo viditeľnej šírke vrátane okraja */
  overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x mandatory; scrollbar-width: none;
}
.ll-grid::-webkit-scrollbar { display: none; }
.ll-grid > li { scroll-snap-align: start; min-width: 0; }
.ll-grid:focus-visible { outline-offset: 4px; }
.ll-navbar { display: flex; justify-content: flex-end; gap: 8px; margin-top: -12px; padding-inline: 16px; }
.ll.ll .ll-nav {
  width: 40px; height: 40px; border-radius: 50%; display: grid; place-items: center; cursor: pointer;
  border: 1px solid var(--ll-line); background: var(--ll-surface); color: var(--ll-ink);
  transition: background-color .15s ease, opacity .15s ease;
}
.ll-nav svg { width: 18px; height: 18px; }
.ll-nav[data-nav="-1"] svg { transform: rotate(180deg); }
.ll-nav:hover:not(:disabled) { background: var(--ll-card); }
.ll-nav:disabled { opacity: .35; cursor: default; }
/* na dotykových zariadeniach sa posúva prstom – šípky netreba */
@media (hover: none) { .ll-navbar { display: none; } }
/* na počítači: šípky po stranách pásu namiesto samostatného riadku */
@media (hover: hover) and (min-width: 700px) {
  .ll-navbar { position: absolute; inset: 0 0 28px; margin: 0; padding: 0; justify-content: space-between; align-items: center; pointer-events: none; }
  .ll-navbar[hidden] { display: none; }
  .ll.ll .ll-nav { pointer-events: auto; box-shadow: var(--ll-shadow-hi); width: 44px; height: 44px; margin-inline: -8px; }
  .ll-nav:disabled { opacity: 0; pointer-events: none !important; }
}
/* viac kariet naraz na širších blokoch */
@container (min-width: 620px) { .ll.ll .ll-grid { grid-auto-columns: calc((100% + 16px - 2 * var(--ll-gap)) / 2.4); } }
@container (min-width: 960px) { .ll.ll .ll-grid { grid-auto-columns: calc((100% + 16px - 3 * var(--ll-gap)) / 3.4); } }

/* ---------- panel: odkiaľ, zoradenie, čerstvosť ---------- */
.ll-toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 20px; }
.ll-bar { display: flex; align-items: center; gap: 10px; min-width: 0; max-width: 100%; }
.ll-bar-label { flex: none; font-size: 12px; font-weight: 600; color: var(--ll-ink-2); text-transform: uppercase; letter-spacing: .04em; }
.ll-chips { display: flex; gap: 6px; overflow-x: auto; scrollbar-width: none; padding: 2px; margin: -2px; }
.ll-chips::-webkit-scrollbar { display: none; }
.ll-chips button {
  flex: none; border: 1px solid var(--ll-line); background: var(--ll-surface); color: var(--ll-ink-2); cursor: pointer; white-space: nowrap;
  padding: 9px 14px; border-radius: 999px; font: 600 13px/1 var(--ll-font); transition: background-color .15s ease, color .15s ease, border-color .15s ease;
}
.ll-chips button:hover { color: var(--ll-ink); border-color: var(--ll-ink-2); }
.ll-chips button[aria-pressed="true"] { background: var(--ll-accent); border-color: var(--ll-accent); color: #131313; }
.ll-fresh { margin-left: auto; display: inline-flex; gap: 8px; align-items: center; font-size: 12px; font-weight: 600; color: var(--ll-ink-2); }
.ll-fresh i { width: 7px; height: 7px; border-radius: 50%; background: var(--ll-good); }
@media (max-width: 640px) {
  .ll-toolbar { gap: 8px; }
  .ll-bar { width: 100%; }
  .ll-fresh { margin-left: 0; }
}

/* ---------- hlavička sekcie s počtom ponúk ---------- */
.ll-sect-head { display: flex; justify-content: space-between; align-items: flex-end; gap: 12px; }
.ll-count { flex: none; font-size: 12px; font-weight: 600; color: var(--ll-ink-2); padding: 5px 10px; border-radius: 999px; background: var(--ll-card); }
.ll-card-id { display: inline-flex; align-items: center; gap: 8px; flex-wrap: wrap; min-width: 0; }
.ll-best { font-size: 11px; font-weight: 700; padding: 3px 8px; border-radius: 999px; background: var(--ll-accent); color: #131313; white-space: nowrap; }

/* výber oblasti pod ponukami */
.ll-filter { justify-self: center; display: inline-flex; gap: 4px; padding: 4px; border-radius: 999px; background: var(--ll-card); max-width: 100%; }
.ll-filter button {
  border: 0; background: transparent; cursor: pointer; white-space: nowrap;
  padding: 10px clamp(12px, 0.6rem + 1vw, 20px); border-radius: 999px;
  font: 600 14px/1 var(--ll-font); color: var(--ll-ink-2); transition: background-color .15s ease, color .15s ease;
}
.ll-filter button:hover { color: var(--ll-ink); }
.ll-filter button[aria-pressed="true"] { background: var(--ll-accent); color: #131313; }
.ll-card {
  height: 100%; display: grid; grid-template-rows: auto auto 1fr auto; gap: 14px;
  padding: clamp(14px, 1.2rem + 0.4vw, 20px); border-radius: clamp(14px, 1rem + 0.5vw, 20px); background: var(--ll-card); border: 1px solid transparent;
  color: inherit; text-decoration: none;
  transition: transform .2s ease, box-shadow .2s ease, background-color .2s ease, border-color .2s ease;
}
.ll-card:hover { transform: translateY(-3px); background: var(--ll-card-hover); border-color: var(--ll-line); box-shadow: var(--ll-shadow-hi); }
.ll-card-top { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.ll-route { display: inline-flex; gap: 6px; align-items: center; font: 600 12px/1 var(--ll-mono); color: var(--ll-ink-2); letter-spacing: .02em; }
.ll-route svg { width: 13px; height: 13px; color: var(--ll-accent); }
.ll-chip { font-size: 12px; font-weight: 600; padding: 4px 9px; border-radius: 999px; background: var(--ll-surface); color: var(--ll-ink-2); white-space: nowrap; }
.ll-card:hover .ll-chip { background: var(--ll-soft); }
.ll.ll .ll-city { font: 700 clamp(18px, 1rem + 0.45vw, 22px)/1.15 var(--ll-font); letter-spacing: -.015em; overflow-wrap: anywhere; }
.ll.ll .ll-country { margin-top: 2px; font-size: 14px; color: var(--ll-ink-2); }
.ll.ll .ll-dates { display: flex; gap: 8px; align-items: flex-start; font-size: 13px; color: var(--ll-ink-2); line-height: 1.4; }
.ll-dates svg { flex: none; width: 15px; height: 15px; margin-top: 1px; }
.ll-card-bottom { display: flex; justify-content: space-between; align-items: flex-end; gap: 10px; padding-top: 14px; border-top: 1px solid var(--ll-line); }
.ll-price { display: grid; gap: 4px; }
.ll-price small { font-size: 12px; color: var(--ll-ink-2); }
.ll-price strong { font: 700 clamp(22px, 1.2rem + 0.6vw, 28px)/1 var(--ll-font); letter-spacing: -.02em; }
.ll-price-label { display: flex; gap: 8px; align-items: center; min-height: 20px; }
.ll-source { font-size: 12px; font-weight: 600; color: var(--ll-ink-2); }
.ll-source[data-src="ryanair"]::before, .ll-source[data-src="wizzair"]::before, .ll-source[data-src="momondo"]::before {
  content: ""; display: inline-block; width: 7px; height: 7px; border-radius: 50%; margin-right: 6px; vertical-align: 1px;
}
.ll-source[data-src="ryanair"]::before { background: #1f4bb8; }
.ll-source[data-src="wizzair"]::before { background: #c6007e; }
.ll-source[data-src="momondo"]::before { background: #ff6a4d; }
.ll-change { font-size: 11px; font-weight: 700; padding: 2px 6px; border-radius: 6px; white-space: nowrap; }
.ll-change.is-down { color: var(--ll-good); background: var(--ll-good-soft); }
.ll-change.is-up { color: var(--ll-ink-2); background: var(--ll-surface); font-weight: 600; }
.ll-go {
  flex: none; width: 40px; height: 40px; border-radius: 50%; display: grid; place-items: center;
  background: var(--ll-surface); color: var(--ll-accent); transition: background-color .2s ease, color .2s ease;
}
.ll-go svg { width: 18px; height: 18px; transition: transform .2s ease; }
.ll-card:hover .ll-go { background: var(--ll-accent); color: #131313; }
.ll-card:hover .ll-go svg { transform: translateX(2px); }

/* ---------- tlačidlo Vyhľadaj aktuálne lacné letenky (pod ponukami) ---------- */
.ll-actions { display: grid; justify-items: center; gap: 12px; }
.ll-actions .ll-msg { width: 100%; text-align: center; }
.ll-refresh {
  display: inline-flex; gap: 10px; align-items: center; justify-content: center; white-space: nowrap;
  border: 0; cursor: pointer; padding: 15px 24px; border-radius: 999px;
  background: var(--ll-accent); color: #131313; font: 700 16px/1 var(--ll-font);
  box-shadow: 0 10px 24px -10px color-mix(in srgb, var(--ll-accent) 70%, transparent);
  transition: transform .15s ease, filter .15s ease, box-shadow .15s ease;
}
.ll-refresh:hover { filter: brightness(1.08); transform: translateY(-1px); }
.ll-refresh:active { transform: translateY(0); }
.ll-refresh svg { width: 18px; height: 18px; }
.ll-refresh[aria-busy="true"] { cursor: progress; filter: saturate(.8); }
.ll-refresh[aria-busy="true"] svg { animation: ll-spin .9s linear infinite; }
@keyframes ll-spin { to { transform: rotate(360deg); } }
.ll.ll .ll-msg { padding: 12px 16px; border-radius: 14px; background: var(--ll-accent-soft); color: var(--ll-ink); font-size: 14px; }

/* ---------- sledovaná destinácia (Bangkok) ---------- */
.ll-feature {
  position: relative; overflow: hidden; isolation: isolate;
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 20px 32px; align-items: end;
  padding: clamp(22px, 3.5vw, 36px); border-radius: 24px;
  background: var(--ll-feature); color: var(--ll-feature-ink); text-decoration: none;
  transition: transform .2s ease, box-shadow .2s ease;
}
.ll-feature:hover { transform: translateY(-2px); box-shadow: 0 20px 40px -18px rgba(15, 23, 42, .5); }
.ll-feature-arc { position: absolute; right: 0; top: 0; width: 60%; height: 100%; z-index: -1; }
.ll-feature-arc path { fill: none; stroke: rgba(255, 255, 255, .16); stroke-width: 1.5; stroke-dasharray: 4 7; vector-effect: non-scaling-stroke; }
.ll-feature-main { display: grid; gap: 10px; min-width: 0; }
.ll.ll .ll-feature-kicker { display: inline-flex; gap: 8px; align-items: center; font-size: 13px; font-weight: 600; color: var(--ll-feature-ink-2); }
.ll-feature-kicker::before {
  content: ""; flex: none; width: 7px; height: 7px; border-radius: 50%; background: #5fd3a2;
  box-shadow: 0 0 0 0 rgba(95, 211, 162, .55); animation: ll-pulse 1.8s ease-out infinite;
}
@keyframes ll-pulse {
  0% { box-shadow: 0 0 0 0 rgba(95, 211, 162, .55); }
  70% { box-shadow: 0 0 0 9px rgba(95, 211, 162, 0); }
  100% { box-shadow: 0 0 0 0 rgba(95, 211, 162, 0); }
}
@media (prefers-reduced-motion: reduce) {
  .ll-feature-kicker::before { animation: none; box-shadow: 0 0 0 4px rgba(95, 211, 162, .18); }
}
.ll.ll .ll-feature-city { font: 700 clamp(34px, 5.5vw, 52px)/1 var(--ll-font); letter-spacing: -.03em; }
.ll.ll .ll-feature-meta { display: flex; flex-wrap: wrap; gap: 6px 14px; align-items: center; font-size: 14px; color: var(--ll-feature-ink-2); }
.ll-feature-meta svg { width: 15px; height: 15px; }
.ll-feature .ll-route { color: var(--ll-feature-ink); }
.ll-feature .ll-route svg { color: var(--ll-accent); }
.ll-feature-side { display: grid; justify-items: end; gap: 6px; text-align: right; }
.ll-feature-side small { font-size: 13px; color: var(--ll-feature-ink-2); }
.ll-feature-side strong { font: 700 clamp(40px, 6vw, 56px)/1 var(--ll-font); letter-spacing: -.03em; }
.ll-feature .ll-change.is-down { background: rgba(95, 211, 162, .16); color: #7ee2b5; }
.ll-feature .ll-change.is-up { background: rgba(255, 255, 255, .1); color: var(--ll-feature-ink-2); }
.ll-feature-cta {
  margin-top: 8px; display: inline-flex; gap: 8px; align-items: center; white-space: nowrap;
  background: var(--ll-accent); color: #131313; font-weight: 700; font-size: 14px; padding: 12px 18px; border-radius: 999px;
}
.ll-feature-cta svg { width: 16px; height: 16px; transition: transform .2s ease; }
.ll-feature:hover .ll-feature-cta svg { transform: translateX(3px); }
.ll-watch-empty { display: flex; flex-wrap: wrap; gap: 8px 20px; justify-content: space-between; align-items: center; padding: 16px 20px; border-radius: 16px; background: var(--ll-card); font-size: 14px; color: var(--ll-ink-2); }
.ll-watch-empty b { color: var(--ll-ink); }

/* ---------- počasie v destinácii v deň príletu ---------- */
.ll.ll .ll-wx {
  display: inline-flex; align-items: center; gap: 4px; padding: 2px 9px 2px 5px; border-radius: 999px;
  background: var(--ll-surface); color: var(--ll-ink); font-weight: 600; font-size: 12px; line-height: 1.4;
  white-space: nowrap; font-variant-numeric: tabular-nums;
}
.ll.ll .ll-wx svg { flex: none; width: 18px; height: 18px; margin: 0; }
.ll-city-row { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 10px; }
.ll-city-row .ll-city { min-width: 0; }
.ll-row-head { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 8px; }
.ll.ll .ll-row-head .ll-wx { font-size: 11px; padding: 1px 7px 1px 4px; }
.ll.ll .ll-row-head .ll-wx svg { width: 16px; height: 16px; }
.ll.ll .ll-feature .ll-wx { background: rgba(255, 255, 255, .14); color: inherit; font-size: 13px; }

.ll-sect { display: grid; gap: 14px; }
.ll.ll .ll-sect-title { font: 700 clamp(19px, 1rem + 0.7vw, 24px)/1.2 var(--ll-font); letter-spacing: -.02em; color: var(--ll-ink); text-wrap: balance; }
.ll.ll .ll-sub { font-size: 13px; color: var(--ll-ink-2); margin: 2px 0 0; }

/* ---------- zoznam Ázia a SAE pod Bangkokom ---------- */
.ll-list-wrap { display: grid; gap: 10px; }
.ll.ll .ll-list-title { font: 700 clamp(15px, 0.85rem + 0.3vw, 17px)/1.3 var(--ll-font); color: var(--ll-ink); letter-spacing: -.01em; }
.ll.ll .ll-list { border-radius: clamp(14px, 1rem + 0.5vw, 20px); background: var(--ll-card); overflow: hidden; }
.ll.ll .ll-list > li + li { border-top: 1px solid var(--ll-line); }
.ll-row {
  display: grid; align-items: center; gap: 6px clamp(12px, 0.5rem + 1.5vw, 24px);
  grid-template-columns: minmax(0, 1.3fr) minmax(0, 1.2fr) auto auto;
  padding: clamp(9px, 0.45rem + 0.3vw, 12px) clamp(14px, 0.8rem + 0.8vw, 22px);
  color: inherit; text-decoration: none; transition: background-color .15s ease;
}
a.ll-row:hover { background: var(--ll-surface); }
.ll-row-main { display: grid; gap: 2px; min-width: 0; }
.ll-row-name { font: 700 clamp(14px, 0.8rem + 0.3vw, 16px)/1.2 var(--ll-font); color: var(--ll-ink); }
.ll-row-sub { font-size: 12px; color: var(--ll-ink-2); overflow-wrap: anywhere; }
.ll-row-sub .ll-alt-origin { font-weight: 600; color: var(--ll-accent); }
.ll-row-sub .ll-route { font-size: 11px; vertical-align: 1px; }
.ll-row-dates { display: flex; gap: 8px; align-items: center; font-size: 13px; color: var(--ll-ink-2); min-width: 0; }
.ll-row-dates svg { flex: none; width: 15px; height: 15px; }
.ll-row-price { display: grid; justify-items: end; gap: 1px; text-align: right; }
.ll-row-price small { font-size: 11px; color: var(--ll-ink-2); }
.ll-row-price strong { font: 700 clamp(16px, 0.9rem + 0.4vw, 19px)/1 var(--ll-font); letter-spacing: -.02em; color: var(--ll-ink); }
.ll-row-price em { font-style: normal; font-size: 11px; }
.ll-row-go {
  display: inline-flex; gap: 6px; align-items: center; white-space: nowrap;
  font-weight: 700; font-size: 13px; color: var(--ll-accent); text-decoration: none;
  padding: 7px 12px; border-radius: 999px; background: var(--ll-surface);
}
.ll-row-go svg { width: 14px; height: 14px; transition: transform .2s ease; }
a.ll-row:hover .ll-row-go svg, .ll-row-go:hover svg { transform: translateX(2px); }
.ll-row.is-empty .ll-row-name { color: var(--ll-ink-2); }
.ll-row.is-empty .ll-row-go { background: transparent; }
.ll.ll .ll-list > li[hidden] { display: none; }
.ll.ll .ll-list-toggle {
  justify-self: center; display: inline-flex; gap: 6px; align-items: center;
  font: 600 13px/1 var(--ll-font); color: var(--ll-accent); background: none; border: 0;
  padding: 8px 12px; border-radius: 999px; cursor: pointer;
}
.ll.ll .ll-list-toggle:hover { background: var(--ll-surface); }
.ll.ll .ll-list-toggle:focus-visible { outline: 2px solid var(--ll-accent); outline-offset: 2px; }
.ll-list-toggle svg { width: 16px; height: 16px; transition: transform .2s ease; }
.ll-list-toggle[aria-expanded="true"] svg { transform: rotate(180deg); }

/* ---------- pätička a prázdny stav ---------- */
.ll-foot { font-size: 13px; line-height: 1.5; color: var(--ll-ink-2); }
.ll.ll .ll-foot a { color: inherit; text-decoration: underline; text-underline-offset: 2px; }
.ll-more { color: var(--ll-accent); font-weight: 600; text-decoration: none; display: inline-flex; gap: 6px; align-items: center; }
.ll-more:hover { text-decoration: underline; text-underline-offset: 3px; }
.ll-empty { padding: 40px 20px; border: 1px dashed var(--ll-line); border-radius: 16px; text-align: center; color: var(--ll-ink-2); display: grid; gap: 6px; justify-items: center; }
.ll-empty b { color: var(--ll-ink); font-size: 16px; }

/* skeleton pri načítaní */
.ll-skel { height: 230px; border-radius: 16px; background: linear-gradient(90deg, var(--ll-soft), var(--ll-surface), var(--ll-soft)); background-size: 200% 100%; animation: ll-shimmer 1.4s linear infinite; }
@keyframes ll-shimmer { to { background-position: -200% 0; } }

/* mobil: karta Bangkoku, zoznam a tlačidlo */
@media (max-width: 640px) {
  .ll-row { grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "main price" "dates price"; row-gap: 3px; }
  .ll-row-main { grid-area: main; }
  .ll-row-price { grid-area: price; }
  .ll-row-dates { grid-area: dates; font-size: 12px; }
  .ll-row-dates svg { width: 13px; height: 13px; }
  a.ll-row .ll-row-go, .ll-row-price em { display: none; }
  .ll-row.is-empty { grid-template-areas: "main go" "dates go"; }
  .ll-row.is-empty .ll-row-price { display: none; }
  .ll-row-go { grid-area: go; justify-self: end; padding: 6px 10px; }
  .ll-refresh { width: 100%; white-space: normal; line-height: 1.25; }
  .ll-filter { display: flex; width: 100%; }
  .ll-filter button { flex: 1 1 0; padding-inline: 8px; }
  .ll-feature { grid-template-columns: 1fr; align-items: start; }
  .ll-feature-side { justify-items: start; text-align: left; grid-template-columns: 1fr auto; align-items: end; }
  .ll-feature-side small { grid-column: 1 / -1; }
  .ll-feature-side .ll-change { grid-column: 1 / -1; justify-self: start; }
  .ll-feature-cta { margin-top: 8px; grid-column: 1 / -1; justify-content: center; }
  .ll-feature-arc { width: 100%; }
}

@media (prefers-reduced-motion: reduce) {
  .ll *, .ll *::before { animation: none !important; transition: none !important; }
  .ll-card:hover, .ll-feature:hover { transform: none; }
}

/* ===== RELIFE: nadpisy v písme témy, zaoblenie, stav „vybrané“ ===== */
.ll.ll .ll-title,
.ll.ll .ll-sect-title,
.ll.ll .ll-city,
.ll.ll .ll-feature-city,
.ll.ll .ll-list-title,
.ll .ll-price strong,
.ll .ll-feature-side strong,
.ll .ll-row-price strong,
.ll .ll-row-name { font-family: var(--ll-head); font-weight: 800; }
.ll.ll .ll-title { letter-spacing: -.03em; }
.ll-card { border-radius: 22px; border-color: var(--ll-line); }
.ll-card:hover { border-color: var(--ll-accent); box-shadow: 0 0 0 1px var(--ll-accent), var(--ll-shadow-hi); }
.ll.ll .ll-list { border: 1px solid var(--ll-line); border-radius: 22px; }
.ll-feature { border-radius: 26px; }
.ll-feature:hover { box-shadow: 0 20px 40px -18px rgba(82, 0, 255, .6); }
.ll-feature-arc path { stroke: rgba(255, 255, 255, .22); }
.ll-chip, .ll-wx { border: 1px solid var(--ll-line); }
.ll.ll .ll-msg { border: 1px solid rgba(60, 255, 208, .35); }
.ll-skel { border-radius: 22px; }
.ll :focus-visible { outline-color: var(--ll-accent); }
.ll.ll a { color: inherit; }
.ll.ll .ll-more, .ll.ll .ll-list-toggle, .ll.ll .ll-row-go { color: var(--ll-accent); }
.ll-row-go { border: 1px solid var(--ll-line); }
a.ll-row:hover .ll-row-go { border-color: var(--ll-accent); }
@media (max-width: 760px) { .ll.ll .ll-title { font-size: clamp(26px, 8vw, 34px); } }

assets.lacne-letenky.js:
/*!
 * Lacné letenky – plugin s najlacnejšími letenkami z Viedne a Bratislavy kamkoľvek.
 * Dáta: data/deals.json (aktualizuje GitHub Actions 3× denne z momondo.co.uk).
 *
 * Vloženie na stránku:
 *   <link rel="stylesheet" href="plugins/lacne-letenky/lacne-letenky.css">
 *   <div data-lacne-letenky data-src="plugins/lacne-letenky/data/deals.json"></div>
 *   <script src="plugins/lacne-letenky/lacne-letenky.js" defer></script>
 *
 * Alebo ručne: LacneLetenky.mount(element, { src: '…/deals.json', limit: 8 })
 *
 * Blok ukazuje iba ponuky z poslednej úspešnej aktualizácie – nikdy nie vymyslené ceny.
 */
(function () {
  'use strict';

  var FONTS = 'https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600;700' +
    '&family=JetBrains+Mono:wght@500;600&display=swap';
  var ARROW = '<svg viewBox="0 0 20 20" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 10h12M11 5l5 5-5 5"/></svg>';
  var CHEVRON = '<svg viewBox="0 0 20 20" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 8l5 5 5-5"/></svg>';
  var PLANE = '<svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor"><path d="M21.5 15.5v-2l-8-5V3.2c0-.9-.7-1.7-1.5-1.7s-1.5.8-1.5 1.7v5.3l-8 5v2l8-2.5v5.2l-2 1.5V21l3.5-1 3.5 1v-1.3l-2-1.5V13l8 2.5z" transform="rotate(90 12 12)"/></svg>';
  var CAL = '<svg viewBox="0 0 20 20" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><rect x="3" y="4.5" width="14" height="12.5" rx="2.5"/><path d="M3 8.5h14M7 2.5v4M13 2.5v4"/></svg>';

  // Počasie v destinácii v deň príletu (Open-Meteo): ikony podľa typu počasia
  var WX_SUN = '<circle cx="12" cy="12" r="4.2" fill="#f5b301" stroke="none"/><g stroke="#f5b301"><path d="M12 2.5v2.2M12 19.3v2.2M2.5 12h2.2M19.3 12h2.2M5.3 5.3l1.5 1.5M17.2 17.2l1.5 1.5M5.3 18.7l1.5-1.5M17.2 6.8l1.5-1.5"/></g>';
  var WX_CLOUD = '<path d="M7.5 19h9.3a4 4 0 0 0 .5-8 5.5 5.5 0 0 0-10.6 1.3A3.4 3.4 0 0 0 7.5 19z" fill="#e3e8ef" stroke="#8a97a8"/>';
  var WX = {
    sun: { label: 'slnečno', svg: WX_SUN },
    partly: { label: 'polooblačno', svg: '<g transform="translate(-3 -3) scale(.8)">' + WX_SUN + '</g><path d="M9 20h8.3a3.6 3.6 0 0 0 .4-7.2 5 5 0 0 0-9.6 1.2A3 3 0 0 0 9 20z" fill="#e3e8ef" stroke="#8a97a8"/>' },
    cloud: { label: 'oblačno', svg: WX_CLOUD },
    fog: { label: 'hmla', svg: '<g stroke="#8a97a8"><path d="M4 9h16M6 13h12M4 17h16"/></g>' },
    rain: { label: 'dážď', svg: '<path d="M7.5 15h9.3a4 4 0 0 0 .5-8 5.5 5.5 0 0 0-10.6 1.3A3.4 3.4 0 0 0 7.5 15z" fill="#e3e8ef" stroke="#8a97a8"/><g stroke="#2f7de1"><path d="M8.5 18l-1 2.5M12.5 18l-1 2.5M16.5 18l-1 2.5"/></g>' },
    snow: { label: 'sneh', svg: '<path d="M7.5 15h9.3a4 4 0 0 0 .5-8 5.5 5.5 0 0 0-10.6 1.3A3.4 3.4 0 0 0 7.5 15z" fill="#e3e8ef" stroke="#8a97a8"/><g fill="#6aa9f0" stroke="none"><circle cx="8.5" cy="19" r="1.2"/><circle cx="12.5" cy="20.5" r="1.2"/><circle cx="16.5" cy="19" r="1.2"/></g>' },
    storm: { label: 'búrky', svg: '<path d="M7.5 15h9.3a4 4 0 0 0 .5-8 5.5 5.5 0 0 0-10.6 1.3A3.4 3.4 0 0 0 7.5 15z" fill="#d5dbe4" stroke="#6b7789"/><path d="M12.5 15l-2.5 4h3l-2 3.5" fill="none" stroke="#f5b301"/>' }
  };

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function money(v, cur) {
    try {
      return new Intl.NumberFormat('sk-SK', { style: 'currency', currency: cur || 'EUR', currencyDisplay: 'narrowSymbol', maximumFractionDigits: 0 }).format(v);
    } catch (e) { return v + ' ' + (cur || ''); }
  }
  function day(iso) {
    if (!iso) return '';
    return new Date(iso + 'T12:00:00').toLocaleDateString('sk-SK', { weekday: 'short', day: 'numeric', month: 'short' });
  }
  function time(iso) {
    return new Date(iso).toLocaleTimeString('sk-SK', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Vienna' });
  }
  function relDay(iso) {
    var d = new Date(iso), now = new Date();
    var fmt = function (x) { return x.toLocaleDateString('sv-SE', { timeZone: 'Europe/Vienna' }); };
    if (fmt(d) === fmt(now)) return 'dnes';
    if (fmt(d) === fmt(new Date(now.getTime() - 864e5))) return 'včera';
    if (fmt(d) === fmt(new Date(now.getTime() + 864e5))) return 'zajtra';
    return d.toLocaleDateString('sk-SK', { day: 'numeric', month: 'short', timeZone: 'Europe/Vienna' });
  }
  function nights(n) {
    if (n == null) return 'jednosmerne';
    if (n === 1) return '1 noc';
    if (n >= 2 && n <= 4) return n + ' noci';
    return n + ' nocí';
  }
  function stopsLabel(s) {
    if (s == null) return '';
    if (s === 0) return 'Priamy let';
    if (s === 1) return '1 prestup';
    return s + ' prestupy';
  }
  function ensureFonts() {
    if (document.querySelector('link[data-ll-fonts]')) return;
    var l = document.createElement('link');
    l.rel = 'stylesheet'; l.href = FONTS; l.setAttribute('data-ll-fonts', '');
    document.head.appendChild(l);
  }

  var SOURCES = { momondo: 'momondo', ryanair: 'Ryanair', wizzair: 'Wizz Air' };
  function sourceName(d) { return SOURCES[d.source] || 'momondo'; }
  var REFRESH = '<svg viewBox="0 0 20 20" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M16.5 10a6.5 6.5 0 1 1-1.9-4.6M16.5 3.5v3.5H13"/></svg>';
  // Ponuky staršie ako toto sa už nezobrazia (aktualizácia zlyhala viackrát po sebe).
  var MAX_AGE_H = 36;
  var LIST_PREVIEW = 3; // koľko riadkov zoznamu Ázia a SAE je vidno pred rozbalením
  var listSeq = 0;
  // Hľadáme lety s odletom najviac 3 mesiace dopredu (rovnako ako scripts/update_deals.py).
  var HORIZON_DAYS = 92;

  function viennaDate(offsetDays) {
    return new Date(Date.now() + (offsetDays || 0) * 864e5).toLocaleDateString('sv-SE', { timeZone: 'Europe/Vienna' });
  }
  function isFresh(data) {
    return !!data.updatedAt && (Date.now() - new Date(data.updatedAt).getTime()) / 36e5 <= MAX_AGE_H;
  }
  function inWindow(d) {
    return !!d.depart && d.depart > viennaDate(0) && d.depart <= viennaDate(HORIZON_DAYS);
  }
  function freshDeals(data) {
    if (!isFresh(data)) return [];
    return (data.deals || []).filter(inWindow).sort(function (a, b) { return a.price - b.price; });
  }

  // Načíta dáta. fresh=true obíde cache prehliadača, aby tlačidlo vždy dostalo najnovší deals.json.
  function loadData(opts, fresh) {
    if (fresh && opts.src) {
      // refresh=1: WordPress plugin spustí živé hľadanie (momondo + Ryanair); statický deals.json ho ignoruje
      var url = opts.src + (opts.src.indexOf('?') > -1 ? '&' : '?') + 'refresh=1&t=' + Date.now();
      return fetch(url, { cache: 'no-store' }).then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      });
    }
    if (opts.data) return Promise.resolve(opts.data);
    if (window.LACNE_LETENKY_DATA) return Promise.resolve(window.LACNE_LETENKY_DATA);
    return fetch(opts.src || 'data/deals.json', { cache: 'no-cache' }).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.json();
    });
  }

  function mount(el, opts) {
    opts = opts || {};
    if (opts.fonts !== false) ensureFonts();
    el.classList.add('ll');
    el.setAttribute('role', 'region');
    el.setAttribute('aria-label', 'Lacné letenky z Viedne a Bratislavy');

    el.innerHTML = '<div class="ll-grid"><div class="ll-skel"></div><div class="ll-skel"></div><div class="ll-skel"></div><div class="ll-skel"></div></div>';
    return loadData(opts, false).then(function (data) {
      render(el, data, opts, '');
      // aktuálne ceny pri každom otvorení stránky (WordPress: živé hľadanie, výsledok platí pár minút)
      if (opts.autoRefresh && opts.src) search(el, data, opts, true);
    }, function (err) {
      el.innerHTML = '<div class="ll-empty"><p>Letenky sa nepodarilo načítať (' + esc(err.message) +
        '). Skontrolujte cestu k súboru deals.json v atribúte data-src.</p></div>';
    });
  }

  // Partnerské odkazy: šablóna odkazu pre každú spoločnosť (momondo, ryanair, wizzair, pegasus, default).
  // Šablóna obaľuje pôvodný odkaz na let: {url} alebo {url_enc} (zakódovaný), ďalej {origin}, {dest},
  // {depart}, {return}, {source}. Bez šablóny sa použije pôvodný odkaz.
  function affiliateFor(opts, d) {
    var a = opts.affiliate || {};
    var tpl = a[d.source] || a['default'] || '';
    if (!tpl || !d.url) return null;
    var vars = { url: d.url, url_enc: encodeURIComponent(d.url), origin: d.origin, dest: d.dest,
      depart: d.depart || '', 'return': d['return'] || '', source: d.source || '' };
    return tpl.replace(/\{(\w+)\}/g, function (m, k) { return vars.hasOwnProperty(k) ? vars[k] : m; });
  }
  function hasAffiliate(opts) {
    var a = opts.affiliate || {};
    return Object.keys(a).some(function (k) { return !!a[k]; });
  }

  function render(el, data, opts, note) {
    var fresh = isFresh(data);
    // Bangkok (a ďalšie sledované mestá): iba spiatočná letenka v najbližších 3 mesiacoch.
    var watch = (data.watch || []).map(function (w) {
      var d = w.deal;
      return {
        name: w.name, airports: w.airports || [], searchUrl: w.searchUrl, featured: w.featured === true || (w.featured == null && w.name === 'Bangkok'), list: w.list === true, note: w.note,
        deal: fresh && d && d['return'] && inWindow(d) ? d : null
      };
    });
    // featured (Bangkok) = veľká karta; list (Ázia, SAE) = zoznam pod ňou;
    // ostatné sledované mestá sa vždy pridajú medzi karty
    // v zozname iba destinácie, do ktorých som našiel spiatočnú letenku
    var listed = watch.filter(function (w) { return !w.featured && w.list && w.deal; });
    var listId = el.getAttribute('data-ll-list') || 'll-list-' + (++listSeq);
    el.setAttribute('data-ll-list', listId);
    var pinned = watch.filter(function (w) { return !w.featured && !w.list; });
    var pinnedDeals = pinned.filter(function (w) { return w.deal; })
      .map(function (w) {
        var d = {}; for (var k in w.deal) d[k] = w.deal[k];
        d.city = w.name; // jedno letisko = názov destinácie (Malta, Alicante, Catania)
        return d;
      });
    watch = watch.filter(function (w) { return w.featured && w.deal; });
    // sledované mesto (Bangkok) má vlastnú kartu, jeho letiská sa v mriežke neopakujú
    var watched = {};
    (data.watch || []).forEach(function (w) { (w.airports || []).forEach(function (a) { watched[a] = 1; }); });
    var limit = opts.limit || 8;
    // výber pod ponukami: všetky / Európa / mimo Európy
    var region = opts.region || 'all';
    var inRegion = function (d) {
      return region === 'all' || (region === 'eu' ? d.region === 'Európa' : d.region !== 'Európa');
    };
    var pinnedIn = pinnedDeals.filter(inRegion);
    var allDeals = freshDeals(data);
    // odkiaľ (Viedeň / Bratislava / Budapešť) a zoradenie platia pre víkendové aj dlhšie pobyty
    var origin = opts.origin || 'all';
    var sortBy = opts.sort === 'date' ? 'date' : 'price';
    var fromOrigin = function (d) { return origin === 'all' || d.origin === origin; };
    var order = function (a, b) {
      return sortBy === 'date' ? (a.depart < b.depart ? -1 : a.depart > b.depart ? 1 : a.price - b.price) : a.price - b.price;
    };
    var deals = allDeals.filter(function (d) { return !watched[d.dest] && inRegion(d) && fromOrigin(d); })
      .slice(0, limit)           // najlacnejšie ponuky…
      .concat(pinnedIn.filter(fromOrigin))   // …a k nim vždy sledované letiská (Alicante, Sicília, Malta)
      .sort(order);
    var cities = {};
    (data.origins || []).forEach(function (o) { cities[o.code] = o.from || o.city; });
    // predĺžený víkend: odlet štvrtok/piatok, návrat nedeľa/pondelok (zostavuje scripts/update_deals.py)
    var weekendDeals = fresh
      ? (data.weekend || []).filter(function (d) { return d['return'] && inWindow(d) && fromOrigin(d); })
          .sort(function (a, b) { return a.price - b.price; }).slice(0, Math.max(limit, 8)).sort(order)
      : [];

    function datesText(d) {
      return esc(day(d.depart)) + (d['return'] ? ' – ' + esc(day(d['return'])) : '') + ' · ' + nights(d.nights);
    }
    // „☀ 31 °C“ – predpoveď na deň príletu, pri vzdialenejšom termíne odhad z minulých rokov
    function wxHtml(d) {
      var w = d.weather;
      if (!w || w.t == null) return '';
      var k = WX[w.c] || WX.cloud;
      var when = day(d.depart);
      var tip = (w.k === 'f' ? 'Predpoveď počasia' : 'Odhad počasia podľa minulých rokov') + ' – ' + d.city + ', ' + when + ': ' + k.label + ', cez deň okolo ' + w.t + ' °C';
      return '<span class="ll-wx' + (w.k === 'f' ? '' : ' is-est') + '" title="' + esc(tip) + '" aria-label="' + esc(tip) + '">' +
        '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">' + k.svg + '</svg>' +
        '<span>' + (w.k === 'f' ? '' : '~') + w.t + ' °C</span></span>';
    }

    // Zmena ceny oproti predchádzajúcemu hľadaniu – iba pri tom istom lete (letiská aj dátumy).
    function changeHtml(d, long) {
      if (!d.prevPrice || d.prevPrice === d.price) return '';
      var diff = Math.abs(d.prevPrice - d.price), down = d.prevPrice > d.price;
      var when = data.prevUpdatedAt ? ' (' + relDay(data.prevUpdatedAt) + ' ' + time(data.prevUpdatedAt) + ')' : '';
      var tip = 'Pri predchádzajúcom hľadaní' + when + ' stál tento let ' + money(d.prevPrice, d.currency) + '.';
      return '<span class="ll-change ' + (down ? 'is-down' : 'is-up') + '" title="' + esc(tip) + '">' +
        (down ? '▼ o ' : '▲ o ') + money(diff, d.currency) + (down ? ' lacnejšie' : ' drahšie') +
        (long ? ' od posledného hľadania' : '') + '</span>';
    }

    // href + rel odkazu na let; pri partnerskom odkaze rel="sponsored nofollow" (pravidlá Google)
    function linkAttrs(d) {
      var aff = affiliateFor(opts, d);
      return 'href="' + esc(aff || d.url) + '" target="_blank" rel="' + (aff ? 'sponsored nofollow noopener' : 'noopener') + '"';
    }

    function cardHtml(d, best) {
      var from = cities[d.origin] || d.origin;
      var drop = changeHtml(d, false);
      return '<li><a class="ll-card" ' + linkAttrs(d) + ' aria-label="' +
          esc(d.city + ', ' + d.country + ', let z ' + from + ' od ' + money(d.price, d.currency) + '. Otvoriť na ' + sourceName(d)) + '">' +
        '<div class="ll-card-top"><span class="ll-card-id"><span class="ll-route">' + esc(d.origin) + ' ' + PLANE + ' ' + esc(d.dest) + '</span>' +
          '</span>' +
          (stopsLabel(d.stops) ? '<span class="ll-chip">' + stopsLabel(d.stops) + '</span>' : '') + '</div>' +
        '<div><div class="ll-city-row"><p class="ll-city">' + esc(d.city) + '</p>' + wxHtml(d) + '</div><p class="ll-country">' + esc(d.country) + ' · z ' + esc(from) + '</p></div>' +
        '<p class="ll-dates">' + CAL + '<span>' + datesText(d) + '</span></p>' +
        '<div class="ll-card-bottom"><div class="ll-price"><span class="ll-price-label"><small>' + (d['return'] ? 'spiatočná od' : 'od') + '</small>' + drop + (best && !drop ? '<span class="ll-best">Najlacnejšie</span>' : '') + '</span>' +
          '<strong>' + money(d.price, d.currency) + '</strong>' +
          '<span class="ll-source" data-src="' + esc(d.source || 'momondo') + '">cez ' + esc(sourceName(d)) + '</span></div>' +
          '<span class="ll-go" aria-hidden="true">' + ARROW + '</span></div>' +
      '</a></li>';
    }

    function watchHtml(w) {
      var d = w.deal;
      if (!d) {
        return '<div class="ll-watch-empty"><span><b>' + esc(w.name) + '</b> – v najbližších 3 mesiacoch som pri poslednom hľadaní nenašiel spiatočnú letenku.</span>' +
          '<a class="ll-more" href="' + esc(w.searchUrl) + '" target="_blank" rel="noopener">Pozrieť na momondo →</a></div>';
      }
      var from = cities[d.origin] || d.origin;
      var drop = changeHtml(d, true);
      return '<a class="ll-feature" ' + linkAttrs(d) + ' aria-label="' +
          esc(w.name + ', spiatočná letenka z ' + from + ' od ' + money(d.price, d.currency) + '. Otvoriť na ' + sourceName(d)) + '">' +
        '<svg class="ll-feature-arc" viewBox="0 0 400 200" preserveAspectRatio="none" aria-hidden="true"><path d="M10 190 C 120 20, 290 10, 390 70"/></svg>' +
        '<div class="ll-feature-main">' +
          '<p class="ll-feature-kicker">Najlacnejšia spiatočná do ' + esc(w.name === 'Bangkok' ? 'Bangkoku' : w.name) + '</p>' +
          '<p class="ll-feature-city">' + esc(w.name) + '</p>' +
          '<p class="ll-feature-meta"><span class="ll-route">' + esc(d.origin) + ' ' + PLANE + ' ' + esc(d.dest) + '</span>' +
            '<span>z ' + esc(from) + '</span>' + (stopsLabel(d.stops) ? '<span>' + stopsLabel(d.stops) + '</span>' : '') + '</p>' +
          '<p class="ll-feature-meta">' + CAL + '<span>' + datesText(d) + '</span>' + wxHtml(d) + '</p>' +
        '</div>' +
        '<div class="ll-feature-side">' +
          '<small>spiatočná od</small>' +
          '<strong>' + money(d.price, d.currency) + '</strong>' + drop +
          '<span class="ll-feature-cta">Kúpiť ' + ARROW + '</span>' +
        '</div></a>';
    }

    // posuvný pás kariet so šípkami (hlavný aj víkendový)
    function railHtml(list, label) {
      return '<div class="ll-rail">' +
          '<ul class="ll-grid" tabindex="0" aria-label="' + esc(label) + '">' + list.map(function (d, i) { return cardHtml(d, i === 0 && sortBy === 'price' && list.length > 1); }).join('') + '</ul>' +
          '<div class="ll-navbar">' +
            '<button type="button" class="ll-nav" data-nav="-1" aria-label="Predchádzajúce ponuky" disabled>' + ARROW + '</button>' +
            '<button type="button" class="ll-nav" data-nav="1" aria-label="Ďalšie ponuky">' + ARROW + '</button>' +
          '</div>' +
        '</div>';
    }

    function countHtml(n) {
      return n ? '<span class="ll-count">' + n + (n === 1 ? ' ponuka' : n < 5 ? ' ponuky' : ' ponúk') + '</span>' : '';
    }

    // Panel nad ponukami: odkiaľ letím, zoradenie a kedy som ceny vyhľadal
    function toolbarHtml() {
      var counts = {};
      (data.weekend || []).concat(allDeals).forEach(function (d) { counts[d.origin] = (counts[d.origin] || 0) + 1; });
      var origins = [['all', 'Všetky letiská']].concat((data.origins || []).filter(function (o) { return counts[o.code]; })
        .map(function (o) { return [o.code, o.city || o.code]; }));
      if (origins.length < 3 && !fresh) return '';
      return '<div class="ll-toolbar">' +
        '<div class="ll-bar"><span class="ll-bar-label" id="' + listId + '-o">Odlet z</span>' +
          '<div class="ll-chips" role="group" aria-labelledby="' + listId + '-o">' + origins.map(function (o) {
            return '<button type="button" data-origin="' + esc(o[0]) + '" aria-pressed="' + (origin === o[0]) + '">' + esc(o[1]) + '</button>';
          }).join('') + '</div></div>' +
        '<div class="ll-bar"><span class="ll-bar-label" id="' + listId + '-s">Zoradiť</span>' +
          '<div class="ll-chips" role="group" aria-labelledby="' + listId + '-s">' +
            '<button type="button" data-sort="price" aria-pressed="' + (sortBy === 'price') + '">Podľa ceny</button>' +
            '<button type="button" data-sort="date" aria-pressed="' + (sortBy === 'date') + '">Podľa termínu</button>' +
          '</div></div>' +
        (fresh ? '<span class="ll-fresh" title="Ceny vyhľadávam trikrát denne – o 7:00, 12:00 a 18:00."><i aria-hidden="true"></i>Vyhľadané ' + relDay(data.updatedAt) + ' ' + time(data.updatedAt) + '</span>' : '') +
      '</div>';
    }

    function weekendHtml() {
      if (!weekendDeals.length) return '';   // bez nájdenej letenky sekciu nezobrazujeme
      return '<section class="ll-sect ll-weekend" aria-label="Predĺžený víkend">' +
        '<div class="ll-sect-head"><div><h3 class="ll-sect-title">Na predĺžený víkend – najlacnejšie letenky</h3>' +
          '<p class="ll-sub">Odlet vo štvrtok alebo piatok, návrat v nedeľu alebo pondelok (3 až 4 noci).</p></div>' + countHtml(weekendDeals.length) + '</div>' +
        railHtml(weekendDeals, 'Lacné letenky na predĺžený víkend') + '</section>';
    }

    // Kategória 2: najlacnejšie letenky na dlhší pobyt (5–14 nocí) s odletom do 3 mesiacov
    function longHtml() {
      return '<section class="ll-sect ll-long" aria-label="Dlhší pobyt">' +
        '<div class="ll-sect-head"><div><h3 class="ll-sect-title">Najlacnejšie letenky na dlhší pobyt do 3 mesiacov</h3>' +
          '<p class="ll-sub">Odlet do 3 mesiacov, pobyt 5 až 14 nocí.</p></div>' + countHtml(deals.length) + '</div>' +
        (hasAny
          ? '<div class="ll-filter" role="group" aria-label="Oblasť">' + regions.map(function (r) {
              return '<button type="button" data-region="' + r[0] + '" aria-pressed="' + (region === r[0]) + '">' + r[1] + '</button>';
            }).join('') + '</div>'
          : '') +
        (deals.length
          ? railHtml(deals, 'Lacné letenky na dlhší pobyt')
          : hasAny
            ? '<div class="ll-empty"><b>Pre tento výber som teraz nenašiel ponuky</b><span>Skúste iné letisko, inú oblasť alebo nové hľadanie.</span></div>'
            : '<div class="ll-empty"><b>Práve nemáme aktuálne ponuky</b><span>Nové ceny pribudnú pri najbližšom hľadaní o 7:00, 12:00 alebo 18:00.</span></div>') +
        '</section>';
    }

    // Kategória 3: Ázia a Emiráty – veľká karta Bangkoku a zoznam krajín
    function asiaHtml() {
      var feature = watch.map(watchHtml).join('');
      var list = fresh ? listHtml() : '';
      if (!feature && !list) return '';
      return '<section class="ll-sect ll-asia" aria-label="Ázia a Emiráty">' +
        '<div><h3 class="ll-sect-title">Do Ázie a Emirátov – najlacnejšie letenky</h3>' +
          '<p class="ll-sub">Spiatočné letenky do Ázie a Spojených arabských emirátov, odlet do 3 mesiacov – vždy najlacnejšia zo všetkých troch letísk.</p></div>' +
        feature + list + '</section>';
    }

    function listHtml() {
      if (!listed.length) return '';
      var rows = listed.slice().sort(function (a, b) {
        return (a.deal ? a.deal.price : 1e9) - (b.deal ? b.deal.price : 1e9);
      }).map(function (w, i) {
        var d = w.deal;
        // zoznam je zbalený – ďalšie riadky sa ukážu po kliknutí na „Zobraziť všetky“
        var li = '<li' + (i >= LIST_PREVIEW && !opts.listOpen ? ' hidden' : '') + '>';
        if (!d) {
          return li + '<div class="ll-row is-empty">' +
            '<span class="ll-row-main"><b class="ll-row-name">' + esc(w.name) + '</b>' +
              '<span class="ll-row-sub">' + esc(w.note || '') + '</span></span>' +
            '<span class="ll-row-dates">Bez spiatočnej ponuky do 3 mesiacov</span>' +
            '<span class="ll-row-price"></span>' +
            '<a class="ll-row-go" href="' + esc(w.searchUrl) + '" target="_blank" rel="noopener">Hľadať ' + ARROW + '</a>' +
          '</div></li>';
        }
        var from = cities[d.origin] || d.originCity || d.origin;
        return li + '<a class="ll-row" ' + linkAttrs(d) + ' aria-label="' +
            esc(w.name + ', ' + d.city + ', spiatočná letenka z ' + from + ' od ' + money(d.price, d.currency) + '. Otvoriť na ' + sourceName(d)) + '">' +
          '<span class="ll-row-main"><span class="ll-row-head"><b class="ll-row-name">' + esc(w.name) + '</b>' + wxHtml(d) + '</span>' +
            '<span class="ll-row-sub">' + esc(d.city) + ' · <span class="ll-route">' + esc(d.origin) + ' ' + PLANE + ' ' + esc(d.dest) + '</span>' +
            (stopsLabel(d.stops) ? ' · ' + stopsLabel(d.stops) : '') +
            (d.originNote ? ' · <b class="ll-alt-origin">' + esc(d.originNote) + '</b>' : '') + '</span></span>' +
          '<span class="ll-row-dates">' + CAL + '<span>' + datesText(d) + '</span></span>' +
          '<span class="ll-row-price"><small>od</small><strong>' + money(d.price, d.currency) + '</strong>' + changeHtml(d, false) +
            '<em class="ll-source" data-src="' + esc(d.source || 'momondo') + '">cez ' + esc(sourceName(d)) + '</em></span>' +
          '<span class="ll-row-go">Kúpiť ' + ARROW + '</span>' +
        '</a></li>';
      }).join('');
      var more = listed.length - LIST_PREVIEW;
      return '<section class="ll-list-wrap" aria-label="Ázia a SAE">' +
        '<ul class="ll-list" id="' + listId + '">' + rows + '</ul>' +
        (more > 0
          ? '<button type="button" class="ll-list-toggle" data-list-toggle aria-controls="' + listId + '" aria-expanded="' + !!opts.listOpen + '">' +
              '<span>' + (opts.listOpen ? 'Zobraziť menej' : 'Zobraziť všetky (' + listed.length + ')') + '</span>' + CHEVRON + '</button>'
          : '') +
        '</section>';
    }

    var regions = [['all', 'Všetky'], ['eu', 'Európa'], ['world', 'Mimo Európy']];
    var hasAny = allDeals.length > 0;
    var hasWx = allDeals.concat(weekendDeals, watch.map(function (w) { return w.deal; }), listed.map(function (w) { return w.deal; }))
      .some(function (d) { return d && d.weather; });

    // Blok začína rovno ponukami; nadpis sa ukáže, len ak ho web zadá (data-title / Nadpis v nastaveniach).
    el.innerHTML =
      (opts.title ? '<h2 class="ll-title">' + esc(opts.title) + '</h2>' : '') +
      (hasAny || weekendDeals.length ? toolbarHtml() : '') +
      weekendHtml() +   // 1. predĺžený víkend
      longHtml() +      // 2. dlhší pobyt do 3 mesiacov
      asiaHtml() +      // 3. Ázia a Emiráty
      '<div class="ll-actions">' +
        '<button type="button" class="ll-refresh" data-refresh>' + REFRESH + '<span>Vyhľadaj aktuálne lacné letenky</span></button>' +
        '<p class="ll-msg" role="status" aria-live="polite"' + (note ? '' : ' hidden') + '>' + esc(note) + '</p>' +
      '</div>' +
      (hasAny
        ? '<p class="ll-foot">Porovnávam momondo.co.uk, ryanair.com a wizzair.com z Viedne, Bratislavy a Budapešti a ukazujem najnižšiu cenu za osobu v eurách' +
            (data.fx ? ', prepočítané kurzom ECB' + (data.fx.date ? ' z ' + esc(data.fx.date) : '') : '') +
            (fresh ? '. Hľadané ' + relDay(data.updatedAt) + ' ' + time(data.updatedAt) : '') +
            '. Ceny sa menia, pred nákupom ich overte.' +
            (hasAffiliate(opts) ? ' Odkazy na letenky sú partnerské: ak cez ne kúpite, môžem dostať províziu, cena sa pre vás nemení.' : '') +
            (hasWx ? ' Počasie v deň príletu: <a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo.com</a> (predpoveď do 15 dní, ďalej odhad ~ z minulých rokov).' : '') +
            '</p>'
        : '');

    // rozbalenie / zbalenie zoznamu Ázia a SAE
    var toggle = el.querySelector('[data-list-toggle]');
    if (toggle) {
      toggle.addEventListener('click', function () {
        opts.listOpen = !opts.listOpen;
        Array.prototype.forEach.call(el.querySelectorAll('.ll-list > li'), function (li, i) {
          li.hidden = i >= LIST_PREVIEW && !opts.listOpen;
        });
        toggle.setAttribute('aria-expanded', String(opts.listOpen));
        toggle.firstChild.textContent = opts.listOpen ? 'Zobraziť menej' : 'Zobraziť všetky (' + listed.length + ')';
      });
    }

    // výber oblasti – prekreslí ponuky bez nového hľadania
    Array.prototype.forEach.call(el.querySelectorAll('[data-region]'), function (b) {
      b.addEventListener('click', function () {
        opts.region = b.getAttribute('data-region');
        render(el, data, opts, '');
        var again = el.querySelector('[data-region="' + opts.region + '"]');
        if (again) again.focus();
      });
    });

    // odkiaľ a zoradenie – prekreslí ponuky bez nového hľadania
    Array.prototype.forEach.call(el.querySelectorAll('[data-origin],[data-sort]'), function (b) {
      b.addEventListener('click', function () {
        var attr = b.hasAttribute('data-origin') ? 'origin' : 'sort';
        opts[attr] = b.getAttribute('data-' + attr);
        render(el, data, opts, '');
        var again = el.querySelector('[data-' + attr + '="' + opts[attr] + '"]');
        if (again) again.focus();
      });
    });

    // šípky posúvača (myš na počítači); prstom sa posúva priamo – pre každý pás zvlášť
    Array.prototype.forEach.call(el.querySelectorAll('.ll-rail'), function (rail) {
      var grid = rail.querySelector('.ll-grid');
      var navs = rail.querySelectorAll('[data-nav]');
      var navbar = rail.querySelector('.ll-navbar');
      var syncNav = function () {
        var max = grid.scrollWidth - grid.clientWidth - 2;
        navs[0].disabled = grid.scrollLeft <= 2;
        navs[1].disabled = grid.scrollLeft >= max;
        navbar.hidden = max <= 0; // všetko sa zmestí – šípky netreba
        rail.classList.toggle('is-end', max <= 0 || grid.scrollLeft >= max);
      };
      Array.prototype.forEach.call(navs, function (b) {
        b.addEventListener('click', function () {
          var card = grid.querySelector('li');
          var step = card ? card.getBoundingClientRect().width + parseFloat(getComputedStyle(grid).columnGap || 0) : grid.clientWidth / 1.5;
          grid.scrollBy({ left: step * +b.getAttribute('data-nav'), behavior: 'smooth' });
        });
      });
      grid.addEventListener('scroll', syncNav, { passive: true });
      syncNav();
    });

    var btn = el.querySelector('[data-refresh]');
    btn.addEventListener('click', function () { search(el, data, opts, false); });
  }

  // Nové hľadanie: po kliknutí na tlačidlo, alebo automaticky hneď po načítaní stránky (auto = true).
  // Pri automatickom hľadaní sa nič neruší – kým beží, blok ukazuje posledné známe ceny.
  function search(el, data, opts, auto, retry) {
    var btn = el.querySelector('[data-refresh]');
    if (!btn || btn.getAttribute('aria-busy') === 'true') return;
    btn.setAttribute('aria-busy', 'true');
    btn.querySelector('span').textContent = auto ? 'Načítavam aktuálne ceny…' : 'Hľadám najlacnejšie letenky…';
    var started = Date.now();
    var done = function (next, msg) {
      // krátke čakanie, aby hľadanie nepôsobilo ako bliknutie
      setTimeout(function () {
        var lefts = Array.prototype.map.call(el.querySelectorAll('.ll-grid'), function (g) { return g.scrollLeft; });
        render(el, next, opts, msg);
        Array.prototype.forEach.call(el.querySelectorAll('.ll-grid'), function (g, i) { if (lefts[i]) g.scrollLeft = lefts[i]; });
        var b = el.querySelector('[data-refresh]');
        if (b && !auto) b.focus();
      }, auto ? 0 : Math.max(0, 700 - (Date.now() - started)));
    };
    loadData(opts, true).then(function (next) {
      if (!next || !next.updatedAt) {
        done(next && next.updatedAt ? next : data, auto ? '' : 'Ponuky sa ešte pripravujú. Skúste to o chvíľu znova.');
        return;
      }
      // WordPress: výsledok živého hľadania
      if (next.liveBusy) {
        if (auto && !retry) {
          // hľadanie práve spustil iný návštevník – o chvíľu si vezmem jeho výsledok
          setTimeout(function () { btn.removeAttribute('aria-busy'); search(el, data, opts, true, true); }, 6000);
          return;
        }
        done(auto ? data : next, auto ? '' : 'Hľadanie práve prebieha pre iného návštevníka. Skúste to o pár sekúnd.');
        return;
      }
      if (next.liveError) {
        done(next, auto ? '' : 'Nové hľadanie sa teraz nepodarilo, zdroje neodpovedali. Zobrazujem ponuky z ' +
          relDay(next.updatedAt) + ' ' + time(next.updatedAt) + '. Skúste to o chvíľu znova.');
        return;
      }
      if (next.live) {
        done(next, next.liveAgeMin > 0
          ? 'Ponuky sú aktuálne – vyhľadal som ich pred ' + next.liveAgeMin + ' min (' + time(next.updatedAt) + ').'
          : 'Hotovo – najlacnejšie letenky som vyhľadal práve teraz (' + time(next.updatedAt) + ').');
        return;
      }
      if (auto) { done(next, ''); return; }
      var isNew = next.updatedAt && next.updatedAt !== data.updatedAt;
      var when = next.updatedAt ? relDay(next.updatedAt) + ' ' + time(next.updatedAt) : '';
      var nextRun = next.nextUpdate && new Date(next.nextUpdate) > new Date() ? ' Ďalšie hľadanie prebehne ' + relDay(next.nextUpdate) + ' o ' + time(next.nextUpdate) + '.' : '';
      done(next, isNew ? 'Našiel som nové ponuky z hľadania ' + when + '.' : 'Máte najnovšie ponuky z hľadania ' + when + '.' + nextRun);
    }, function () {
      done(data, auto ? '' : 'Nové ponuky sa teraz nepodarilo načítať, zobrazujem posledné známe. Skúste to o chvíľu znova.');
    });
  }

  function auto() {
    document.querySelectorAll('[data-lacne-letenky]').forEach(function (el) {
      if (el.__ll) return;
      el.__ll = true;
      // WordPress plugin vkladá počiatočné dáta priamo do stránky – blok sa ukáže bez čakania
      var initial = null, init = el.querySelector('script[data-ll-initial]');
      if (init) { try { initial = JSON.parse(init.textContent); } catch (e) { initial = null; } }
      if (el.getAttribute('data-font') === 'inherit') el.classList.add('ll-inherit-font');
      mount(el, {
        data: initial || undefined,
        src: el.getAttribute('data-src') || undefined,
        limit: +el.getAttribute('data-limit') || 0,
        title: el.getAttribute('data-title') || undefined,
        affiliate: (function () { try { return JSON.parse(el.getAttribute('data-affiliate') || '') || undefined; } catch (e) { return undefined; } })(),
        fonts: el.getAttribute('data-fonts') !== 'false',
        autoRefresh: el.hasAttribute('data-autoload')
      });
    });
  }

  window.LacneLetenky = { mount: mount };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', auto);
  else auto();
})();

